-------------------------------------------------------------------------------
-- Simprim model for Clock Delay Locked Loop
--
-- Version 1.0
--
-- Dhimant Patel, April, 1998.
-------------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

library STD;
USE STD.TEXTIO.ALL;

entity X_CLKDLL is
    generic (TimingChecksOn    : boolean := TRUE;
             InstancePath : STRING := "*";
             Xon               : boolean := TRUE;
             MsgOn             : boolean := FALSE;

             tipd_CLKIN   : VitalDelayType01 := (0.000 ns, 0.000 ns);
             tipd_CLKFB   : VitalDelayType01 := (0.000 ns, 0.000 ns);
             tipd_RST     : VitalDelayType01 := (0.000 ns, 0.000 ns);

             tpd_CLKIN_LOCKED  : VitalDelayType01 := (0.100 ns, 0.100 ns);

             tperiod_CLKIN_POSEDGE     : VitalDelayType  := 0.010 ns;
             MAXPERCLKIN       : time := 100 ns;

             tpw_CLKIN_posedge : VitalDelayType  := 0.010 ns;
             tpw_CLKIN_negedge : VitalDelayType  := 0.010 ns;

             tpw_RST_posedge   : VitalDelayType  := 0.010 ns;

             DUTY_CYCLE_CORRECTION : boolean := TRUE;
             CLKDV_DIVIDE : real := 2.0);
 
    port (CLKIN   : in  std_ulogic := '0';
          CLKFB   : in  std_ulogic := '0';
          RST     : in  std_ulogic := '0';
          CLK0    : out std_ulogic := '0';
          CLK90   : out std_ulogic := '0';
          CLK180  : out std_ulogic := '0';
          CLK270  : out std_ulogic := '0';
          CLK2X   : out std_ulogic := '0';
          CLKDV   : out std_ulogic := '0';
          LOCKED  : out std_ulogic := '0');

    attribute VITAL_LEVEL0 of X_CLKDLL : entity is TRUE;
 
end X_CLKDLL;
 
architecture X_CLKDLL_V of X_CLKDLL is
 
procedure CHECK_DIVISOR (DIVISOR_IN : in real; signal DIVISOR_OUT : out real;
    signal FRACTIONAL : out boolean
) is

type DIVIDE_BY_ARRAY  is array (0 to 7) of real;
constant DIVIDE_BY_LEGAL : DIVIDE_BY_ARRAY := (1.5, 2.0, 2.5, 3.0, 4.0, 5.0, 8.0, 16.0);
constant DIVIDE_BY_ERROR : string := "(1.5, 2.0, 2.5, 3.0, 4.0, 5.0, 8.0, 16.0)";
variable VALID : boolean := FALSE;
variable X     : real    := 0.0;

begin
    for I in DIVIDE_BY_LEGAL'range loop
        if (DIVISOR_IN = DIVIDE_BY_LEGAL(I)) then
            VALID := TRUE;
        end if;
    end loop;

    if (VALID) then
        X := 2.0 * DIVISOR_IN;
          L : loop
             exit when (X < 2.0);
             X := X - 2.0;
          end loop;
        if (X > 0.0 ) then
            DIVISOR_OUT <= 2.0 * DIVISOR_IN;
            FRACTIONAL  <= TRUE;
        else
            DIVISOR_OUT <= DIVISOR_IN;
        end if;
    else
        assert FALSE report
        "*** Error: CLKDV_DIVIDE is not one of " & DIVIDE_BY_ERROR &
        " , using 2.0 ***"
        severity note;
        DIVISOR_OUT <= 2.0;
    end if;

end CHECK_DIVISOR;

constant CLKIN_WINDOW_WIDTH : time := 100 ps;
constant CLKFB_WINDOW_WIDTH : time := 100 ps;
constant PERIOD_WINDOW_WIDTH : time := 100 ps;
constant DELAY_DELTA         : time := 1   ns;


signal CLKIN_WINDOW         : std_ulogic := '0';
signal CLKFB_WINDOW         : std_ulogic := '0';
signal WINDOW_OVERLAP       : std_ulogic := '0';

signal CLKIN_ipd, CLKFB_ipd, RST_ipd             : std_ulogic := '0';
signal CLK_0, CLK_5050, CLK_2575, CLK_1X,CLK_2X  : std_ulogic := '0';
signal PERIOD_FOUND, FB_DELAY_FOUND              : std_ulogic := '0';
signal RST_META, LOCKED_INT                      : std_ulogic := '0';
signal DCC                                       : std_ulogic := '1';

signal PERIOD, PERIOD_90, PERIOD_180, PERIOD_270 : time := 0 ps;
signal DELAY, FB_DELAY                           : time := 0 ps;

signal CLKIN_DELAYED_0 : std_ulogic := '0';
signal CLK5050_DELAYED_0, CLK2575_DELAYED_0, CLK5050_DELAYED_90 : std_ulogic := '0';

signal DIVISOR : real := 0.0;
signal IS_FRACTIONAL : boolean := FALSE;

begin

    ---------------------
    --  Wire Delays
    ---------------------
    WireDelay : block
    begin
    VitalWireDelay (CLKIN_ipd, CLKIN, tipd_CLKIN);
    VitalWireDelay (CLKFB_ipd, CLKFB, tipd_CLKFB);
    VitalWireDelay (RST_ipd,   RST,   tipd_RST);
    end block;

    CHECK_DIVISOR (DIVISOR_IN  => CLKDV_DIVIDE,
                   DIVISOR_OUT => DIVISOR,
                   FRACTIONAL  => IS_FRACTIONAL);

    ---------------------------------------------------
    --  Generate Master Reset Signal
    ---------------------------------------------------
    RESET_X_CLKDLL : process (RST_ipd, CLKIN_ipd)
    variable COUNT_CLKIN : integer := 0;
    variable RST_EVENT   : boolean := FALSE;
    variable Pviol_RST   : STD_ULOGIC := '0';
    variable PInfo_RST   : VitalPeriodDataType := VitalPeriodDataInit;

    begin
        if(TimingChecksOn) then
            VitalPeriodPulseCheck (
                Violation               => Pviol_RST,
                PeriodData              => PInfo_RST,
                TestSignal              => RST_ipd,
                TestSignalName          => "RST",
                TestDelay               => 0 ns,
                Period                  => 0 ns,
                PulseWidthHigh          => tpw_RST_posedge,
                PulseWidthLow           => 0 ns,
                CheckEnabled            => TRUE,
                HeaderMsg               => InstancePath &"/X_CLKDLL",
                Xon                     => Xon,
                MsgOn                   => TRUE,
                MsgSeverity             => WARNING
            );
        end if;
        if (RST_ipd'event) then
            COUNT_CLKIN := 0;
            RST_EVENT   := TRUE;
        end if;
        if (RST_EVENT) then
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                if (COUNT_CLKIN < 1) then
                    COUNT_CLKIN := COUNT_CLKIN + 1;
                else
                    RST_META <= RST_ipd;
                    RST_EVENT := FALSE;
                end if;
            end if;
        end if;
    end process RESET_X_CLKDLL;

    ---------------------------------------------------
    --  Determine Input Clock Period
    ---------------------------------------------------
    DETERMINE_PERIOD : process
    variable CLKIN_RISE_PREVIOUS, CLKIN_RISE_CURRENT, PERIOD_VAR : time := 0 ps;
    variable PERIOD_PREVIOUS : time := 0 ps;
    variable Pviol_CLKIN : STD_ULOGIC := '0';
    variable PInfo_CLKIN : VitalPeriodDataType := VitalPeriodDataInit;
    variable TEMPLINE : LINE ;
    variable PERIOD_CHANGED : BOOLEAN := false ;
    begin
        if(TimingChecksOn) then
            VitalPeriodPulseCheck (
                Violation               => Pviol_CLKIN,
                PeriodData              => PInfo_CLKIN,
                TestSignal              => CLKIN_ipd,
                TestSignalName          => "CLKIN",
                TestDelay               => 0 ns,
                Period                  => tperiod_CLKIN_POSEDGE,
                PulseWidthHigh          => tpw_CLKIN_posedge,
                PulseWidthLow           => tpw_CLKIN_negedge,
                CheckEnabled            => TRUE,
                HeaderMsg               => InstancePath &"/X_CLKDLL",
                Xon                     => Xon,
                MsgOn                   => TRUE,
                MsgSeverity             => WARNING
            );
        end if;

        if (RST_META = '1' ) then
            CLKIN_RISE_PREVIOUS := 0 ps;
            CLKIN_RISE_CURRENT  := 0 ps;
            PERIOD_PREVIOUS     := 0 ps;
            PERIOD_VAR          := 0 ps;
            PERIOD              <= 0 ps;
            PERIOD_90           <= 0 ps;
            PERIOD_180          <= 0 ps;
            PERIOD_270          <= 0 ps;
            PERIOD_FOUND        <= '0';
        else
            PERIOD_FOUND <= '0';
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                    CLKIN_RISE_PREVIOUS := CLKIN_RISE_CURRENT;
                    CLKIN_RISE_CURRENT  := NOW;
            end if;
            if (CLKIN_RISE_PREVIOUS > 0 ps) then
                PERIOD_PREVIOUS := PERIOD_VAR;
                PERIOD_VAR := CLKIN_RISE_CURRENT - CLKIN_RISE_PREVIOUS;
		PERIOD_CHANGED := false;
                if (PERIOD_VAR > PERIOD_PREVIOUS) then
                    if ((PERIOD_VAR - PERIOD_PREVIOUS) < PERIOD_WINDOW_WIDTH) then
                        PERIOD_VAR := PERIOD_PREVIOUS;
                    else
			PERIOD_CHANGED := TRUE;
                    end if;
                elsif (PERIOD_VAR < PERIOD_PREVIOUS) then
                    if ((PERIOD_PREVIOUS - PERIOD_VAR) < PERIOD_WINDOW_WIDTH) then
                        PERIOD_VAR := PERIOD_PREVIOUS;
                    else
			PERIOD_CHANGED := TRUE;
                    end if;
                end if;
                  if (TimingChecksOn AND PERIOD_CHANGED AND PERIOD_VAR > MAXPERCLKIN) then
                    write(TEMPLINE, STRING'("MAXCLKPERIOD VIOLATION ON CLK;"));

                      write(TEMPLINE, LF );
                      write(TEMPLINE, STRING'("Expected := "));
                      write(TEMPLINE, MAXPERCLKIN );
                      write(TEMPLINE, STRING'( "; Observed := "));
                      write(TEMPLINE, PERIOD_VAR);

                    assert FALSE report
                      TEMPLINE.all & ";"
                      severity warning;
                      --wait;
                 end if;
                PERIOD       <= PERIOD_VAR;
                PERIOD_90    <= PERIOD_VAR * 0.25;
                PERIOD_180   <= PERIOD_VAR * 0.5;
                PERIOD_270   <= PERIOD_VAR * 0.75;
                PERIOD_FOUND <= '1';
            end if;
        end if;

        wait on CLKIN_ipd, RST_META;

    end process DETERMINE_PERIOD;

    ---------------------------------------------------
    --  Determine Feedback Loop Delay
    ---------------------------------------------------
    DETERMINE_FB_DELAY : process (CLKIN_ipd, CLKFB_ipd, RST_META)
    variable TIME_RISE_CLKIN, TIME_RISE_CLKFB : time := 0 ps;
    begin
        if (RST_META'event AND RST_META = '1') then
            TIME_RISE_CLKIN := 0 ps;
            TIME_RISE_CLKFB := 0 ps;
            FB_DELAY_FOUND  <= '0';
            FB_DELAY        <= 0 ps;
        else
             if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                    TIME_RISE_CLKIN := NOW;
             elsif (CLKFB_ipd'event AND CLKFB_ipd = '1') then
                    TIME_RISE_CLKFB := NOW;
             end if;
             if (PERIOD_FOUND = '1' AND FB_DELAY_FOUND = '0' AND TIME_RISE_CLKIN /= 0 ns) then
                if (TIME_RISE_CLKFB > TIME_RISE_CLKIN) then
                    FB_DELAY <= TIME_RISE_CLKFB - TIME_RISE_CLKIN;
                    FB_DELAY_FOUND <= '1';
                end if;
            end if;
        end if;
    end process DETERMINE_FB_DELAY;

    ---------------------------------------------------
    --  Set Lock Delay
    ---------------------------------------------------
    SET_LOCK_DELAY : process (PERIOD, CLKIN_ipd, RST_META)
    variable DELAY_AMOUNT : time := 0 ps;
    variable PERIOD_CHANGED : boolean := FALSE;
    begin
        if (RST_META'event AND RST_META = '1') then
            DELAY   <= 0 ps;
            PERIOD_CHANGED := FALSE;
        elsif (PERIOD'event) then
            PERIOD_CHANGED := TRUE;
        end if;
        if (PERIOD_CHANGED AND FB_DELAY_FOUND = '1') then
            DELAY_AMOUNT := PERIOD - FB_DELAY;
            if ((CLKIN_ipd'event AND CLKIN_ipd = '1') AND LOCKED_INT = '0') then
                if (DELAY_AMOUNT - DELAY > DELAY_DELTA) then
                    DELAY <= DELAY + DELAY_DELTA;
                elsif (DELAY - DELAY_AMOUNT > DELAY_DELTA) then
                    DELAY <= DELAY - DELAY_DELTA;
                else
                    DELAY <= DELAY_AMOUNT;
                end if;
            end if;
        end if;
    end process SET_LOCK_DELAY;

    ---------------------------------------------------
    --  Generate Windows
    ---------------------------------------------------
    GENERATE_WINDOWS : process (CLKIN_ipd, CLKFB_ipd, RST_META)
    begin
        if (RST_META'event AND RST_META = '1') then
            CLKIN_WINDOW <= '0';
            CLKFB_WINDOW <= '0';
        else
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                CLKIN_WINDOW <= '1';
                CLKIN_WINDOW <= transport '0' after CLKIN_WINDOW_WIDTH;
            end if;
            if (CLKFB_ipd'event AND CLKFB_ipd = '1') then
                CLKFB_WINDOW <= '1';
                CLKFB_WINDOW <= transport '0' after CLKFB_WINDOW_WIDTH;
            end if;
        end if;
    end process GENERATE_WINDOWS;
 
    WINDOW_OVERLAP <= CLKIN_WINDOW AND CLKFB_WINDOW;
 
    ---------------------------------------------------
    --  Check for a Lock
    ---------------------------------------------------
    DETERMINE_IF_LOCKED : process (CLKIN_ipd, RST_META, WINDOW_OVERLAP)
    variable LOCKED_GlitchData : VitalGlitchDataType;
    variable IS_LOCKED : std_ulogic := '0';
    begin
        if (RST_META'event AND RST_META = '1') then
            LOCKED_INT <= '0';
            IS_LOCKED  := '0';
        elsif (RST_META /= '1' AND (WINDOW_OVERLAP'event AND WINDOW_OVERLAP = '1')) then
            IS_LOCKED := '1';
        elsif (RST_META /= '1' AND (CLKIN_ipd'event AND CLKIN_ipd = '1')) then
            LOCKED_INT<= IS_LOCKED;
            IS_LOCKED := '0';
        end if;
        ----------------------
        --  Path Delay Section
        ----------------------
        VitalPathDelay01 (
            OutSignal  => LOCKED,
            GlitchData => LOCKED_GlitchData,
            OutSignalName => "LOCKED",
            OutTemp => LOCKED_INT,
            Paths => (0 => (CLKIN_ipd'last_event, tpd_CLKIN_LOCKED, TRUE)),
            Mode => OnEvent,
            Xon => Xon,
            MsgOn => MsgOn,
            MsgSeverity => WARNING
        );

    end process DETERMINE_IF_LOCKED;

    ---------------------------------------------------
    --  Generate CLK_5050 and CLK_2575
    ---------------------------------------------------
    GENERATE_CLOCK_5050_AND_CLK2575 : process (CLKIN_ipd, RST_META)
    begin
        if (RST_META'event AND RST_META = '1') then
            CLK_5050 <= '0';
            CLK_2575 <= '0';
        elsif (PERIOD_FOUND = '1') then
            if (CLKIN_ipd'event AND CLKIN_ipd = '1') then
                CLK_5050 <= '1';
                CLK_2575 <= '1';
                CLK_5050 <= transport '0' after PERIOD_180;
                CLK_2575 <= transport '0' after PERIOD_90;
            end if;
        end if;
    end process GENERATE_CLOCK_5050_AND_CLK2575;
    
    ---------------------------------------------------
    --  Delay CLKIN and CLK_5050 and CLK_2575 for Locking to CLKFB.
    ---------------------------------------------------
    CLKIN_DELAYED_0   <= transport CLKIN_ipd after DELAY;
    CLK5050_DELAYED_0 <= transport CLK_5050  after DELAY;
    CLK2575_DELAYED_0 <= transport CLK_2575  after DELAY;

    ---------------------------------------------------
    --  CLK0, CLK90, CLK180, CLK270, CLK2X and CLK2X90
    ---------------------------------------------------
    DCC <= '1' when DUTY_CYCLE_CORRECTION else '0';
    
 
    CLK_0   <= (PERIOD_FOUND AND (NOT RST_META))  AND
               (((NOT DCC)   AND CLKIN_DELAYED_0)  OR
               (      DCC    AND CLK5050_DELAYED_0));
    CLK0    <= CLK_0;

    CLK90   <= transport CLK_0 after PERIOD_90;
    CLK180  <= transport CLK_0 after PERIOD_180;
    CLK270  <= transport CLK_0 after PERIOD_270;

    CLK5050_DELAYED_90 <= transport CLK_5050 after (DELAY + PERIOD_90);

    CLK_2X  <= (PERIOD_FOUND AND (NOT RST_META)) AND
               (CLK5050_DELAYED_0 XOR CLK5050_DELAYED_90);
    CLK_1X  <= (PERIOD_FOUND AND (NOT RST_META)) AND CLK2575_DELAYED_0;
    CLK2X   <= (LOCKED_INT AND CLK_2X) OR (NOT LOCKED_INT AND CLK_1X);

    ---------------------------------------------------
    --  Clock Divider
    ---------------------------------------------------
    GENERATE_CLOCK_DIV : process (CLK_2X, RST_META)
    variable FIRST_TIME      : boolean    := TRUE;
    variable COUNT_RISE_FALL : real       := 0.0;
    variable CLOCK_DIV       : std_ulogic := '0';
    begin
        if (RST_META = '1') then
            FIRST_TIME      := TRUE;
            COUNT_RISE_FALL := 0.0;
            CLOCK_DIV       := '0';
        elsif (PERIOD_FOUND = '1') then
            if (CLK_2X'event) then
                if (CLK_2X = '1') then
                    if (FIRST_TIME) then
                        CLOCK_DIV  := NOT CLOCK_DIV;
                        FIRST_TIME := FALSE;
                    else COUNT_RISE_FALL := COUNT_RISE_FALL + 1.0;
                    end if;
                end if;
                if (CLK_2X = '0' AND IS_FRACTIONAL) then
                    COUNT_RISE_FALL := COUNT_RISE_FALL + 1.0;
                end if;
                if (COUNT_RISE_FALL >= DIVISOR) then
                    CLOCK_DIV       := NOT CLOCK_DIV;
                    COUNT_RISE_FALL := 0.0;
                end if;
            end if;
            CLKDV <= CLOCK_DIV;
        end if;
    end process GENERATE_CLOCK_DIV;

end X_CLKDLL_V;

configuration CFG_X_CLKDLL_V of X_CLKDLL is
    for X_CLKDLL_V
    end for;
end CFG_X_CLKDLL_V;
----- CELL X_CLKDLL2 -----
-------------------------------------------------------------------------------
-- A V2 Model for Clock Delay Locked Loop
--
-- Version 1.0.0
--
-- Version 1.0.0:
--     Added CLK2X180 pin and functionality. 
--     Added CLKIN_DIVIDE generic.
--     Added input pin NOADJUST.
--     Added output pin NOTINPHASE.
--     Added output pin CLKLOST.
--
-- Version 1.0.0:
--     Initial rev.
--     SG, 6/12/99.
-------------------------------------------------------------------------------
library IEEE;
use IEEE.std_logic_1164.all;
use IEEE.VITAL_Timing.all;

library STD;
USE STD.TEXTIO.ALL;

entity X_CLKDLL2 is
    generic (TimingChecksOn    : boolean := TRUE;
             InstancePath : STRING := "*";
             Xon               : boolean := TRUE;
             MsgOn             : boolean := FALSE;

             tipd_CLKIN   : VitalDelayType01 := (0.000 ns, 0.000 ns);
             tipd_CLKFB   : VitalDelayType01 := (0.000 ns, 0.000 ns);
             tipd_RST     : VitalDelayType01 := (0.000 ns, 0.000 ns);
             tipd_NOADJUST     : VitalDelayType01 := (0.000 ns, 0.000 ns);

             tpd_CLKIN_LOCKED  : VitalDelayType01 := (0.000 ns, 0.000 ns);

             tperiod_CLKIN_POSEDGE     : VitalDelayType  := 0.010 ns;
             MAXPERCLKIN       : time := 100 ns;

             tpw_CLKIN_posedge : VitalDelayType  := 0.010 ns;
             tpw_CLKIN_negedge : VitalDelayType  := 0.010 ns;

             tpw_RST_posedge   : VitalDelayType  := 0.010 ns;

             DUTY_CYCLE_CORRECTION : boolean := TRUE;
             CLKIN_DIVIDE : boolean := FALSE;
             CLKDV_DIVIDE : real := 2.0); 

    port (CLKIN   : in  std_ulogic := '0';
          CLKFB   : in  std_ulogic := '0';
          RST     : in  std_ulogic := '0';
          NOADJUST : in std_ulogic := '0';
          CLK0    : out std_ulogic := '0';
          CLK90   : out std_ulogic := '0';
          CLK180  : out std_ulogic := '0';
          CLK270  : out std_ulogic := '0';
          CLK2X   : out std_ulogic := '0';
          CLK2X180 : out std_ulogic := '0';
          CLKDV   : out std_ulogic := '0';
          CLKLOST : out std_ulogic := '0';
          LOCKED  : out std_ulogic := '0';
          NOTINPHASE : out std_ulogic := '0'
);
 
   attribute VITAL_LEVEL0 of X_CLKDLL2 : entity is TRUE;

end X_CLKDLL2;
 
architecture X_CLKDLL2_V of X_CLKDLL2 is
 
procedure CHECK_DIVISOR (DIVISOR_IN : in real; signal DIVISOR_OUT : out real;
    signal FRACTIONAL : out boolean
) is

type DIVIDE_BY_ARRAY  is array (0 to 21) of real;
constant DIVIDE_BY_LEGAL : DIVIDE_BY_ARRAY := (1.5, 2.0, 2.5, 3.0, 3.5, 4.0, 4.5, 5.0, 5.5, 6.0, 6.5, 7.0, 7.5, 8.0, 9.0, 10.0, 11.0, 12.0, 13.0, 14.0, 15.0, 16.0);
constant DIVIDE_BY_ERROR : string := "(1.5, 2.0, 2.5, 3.0, 3.5, 4.0, 4.5, 5.0, 5.5, 6.0, 6.5, 7.0, 7.5, 8.0, 9.0, 10.0, 11.0, 12.0, 13.0, 14.0, 15.0, 16.0)";
variable VALID : boolean := FALSE;
variable X     : real    := 0.0;

begin
    for I in DIVIDE_BY_LEGAL'range loop
        if (DIVISOR_IN = DIVIDE_BY_LEGAL(I)) then
            VALID := TRUE;
        end if;
    end loop;

    if (VALID) then
        X := 2.0 * DIVISOR_IN;
        L : loop
           exit when (X < 2.0);
           X := X - 2.0;
        end loop;
        if (X > 0.0) then
            DIVISOR_OUT <= 2.0 * DIVISOR_IN;
            FRACTIONAL  <= TRUE;
        else
            DIVISOR_OUT <= DIVISOR_IN;
        end if;
    else
        assert FALSE report
        "*** Error: CLKDV_DIVIDE is not one of " & DIVIDE_BY_ERROR &
        " , using 2.0 ***"
        severity failure;
        DIVISOR_OUT <= 2.0;
    end if;

end CHECK_DIVISOR;

constant CLKIN_WINDOW_WIDTH : time := 100 ps;
constant CLKFB_WINDOW_WIDTH : time := 100 ps;
constant PERIOD_WINDOW_WIDTH : time := 100 ps;
constant DELAY_DELTA         : time := 1   ns;


signal CLKIN_WINDOW         : std_ulogic := '0';
signal CLKFB_WINDOW         : std_ulogic := '0';
signal WINDOW_OVERLAP       : std_ulogic := '0';

signal CLKIN_ipd, CLKIN_DIV, CLKFB_ipd, RST_ipd, NOADJUST_ipd : std_ulogic := '0';
signal CLK_0, CLK_5050, CLK_2575, CLK_1X,CLK_2X  : std_ulogic := '0';
signal PERIOD_FOUND, FB_DELAY_FOUND              : std_ulogic := '0';
signal RST_META, LOCKED_INT                      : std_ulogic := '0';
signal DCC                                       : std_ulogic := '1';

signal PERIOD, PERIOD_90, PERIOD_180, PERIOD_270 : time := 0 ps;
signal DELAY, FB_DELAY                           : time := 0 ps;

signal CLKIN_DELAYED_0 : std_ulogic := '0';
signal CLK5050_DELAYED_0, CLK2575_DELAYED_0, CLK5050_DELAYED_90 : std_ulogic := '0';
signal CLK2X_INT : std_ulogic := '0';

signal DIVISOR : real := 0.0;
signal IS_FRACTIONAL : boolean := FALSE;
signal CLK_CHK : std_ulogic := '0';

begin

    ---------------------
    --  Wire Delays
    ---------------------
    WireDelay : block
    begin
    VitalWireDelay (CLKIN_ipd, CLKIN, tipd_CLKIN);
    VitalWireDelay (CLKFB_ipd, CLKFB, tipd_CLKFB);
    VitalWireDelay (RST_ipd,   RST,   tipd_RST);
    VitalWireDelay (NOADJUST_ipd,   NOADJUST,   tipd_NOADJUST);
    end block;

    CHECK_DIVISOR (DIVISOR_IN  => CLKDV_DIVIDE,
                   DIVISOR_OUT => DIVISOR,
                   FRACTIONAL  => IS_FRACTIONAL);

    CLK_CHK <= NOT CLK_CHK after 50 ns;


    CLKIN_DIVIDER : process (CLKIN_ipd)
    begin
       if (CLKIN_DIVIDE = TRUE ) then
           if (CLKIN_ipd'event and CLKIN_ipd = '1' ) then
              CLKIN_DIV <= NOT CLKIN_DIV;
           end if;
       else
           CLKIN_DIV <= transport CLKIN_ipd;
       end if;

    end process CLKIN_DIVIDER;

    ---------------------------------------------------
    --  Generate Master Reset Signal
    ---------------------------------------------------
    RESET_X_CLKDLL2 : process (RST_ipd, CLKIN_DIV)
    variable COUNT_CLKIN : integer := 0;
    variable RST_EVENT   : boolean := FALSE;
    variable Pviol_RST   : STD_ULOGIC := '0';
    variable PInfo_RST   : VitalPeriodDataType := VitalPeriodDataInit;

    begin
        if(TimingChecksOn) then
            VitalPeriodPulseCheck (
                Violation               => Pviol_RST,
                PeriodData              => PInfo_RST,
                TestSignal              => RST_ipd,
                TestSignalName          => "RST",
                TestDelay               => 0 ns,
                Period                  => 0 ns,
                PulseWidthHigh          => tpw_RST_posedge,
                PulseWidthLow           => 0 ns,
                CheckEnabled            => TRUE,
                HeaderMsg               => InstancePath &"/X_CLKDLL2",
                Xon                     => Xon,
                MsgOn                   => TRUE,
                MsgSeverity             => WARNING
            );
        end if;
        if (RST_ipd'event) then
            COUNT_CLKIN := 0;
            RST_EVENT   := TRUE;
        end if;
        if (RST_EVENT) then
            if (CLKIN_DIV'event AND CLKIN_DIV = '1') then
                if (COUNT_CLKIN < 1) then
                    COUNT_CLKIN := COUNT_CLKIN + 1;
                else
                    RST_META <= RST_ipd;
                    RST_EVENT := FALSE;
                end if;
            end if;
        end if;
    end process RESET_X_CLKDLL2;

    ---------------------------------------------------
    --  Determine Input Clock Period
    ---------------------------------------------------
    DETERMINE_PERIOD : process
    variable CLKIN_RISE_PREVIOUS, CLKIN_RISE_CURRENT, PERIOD_VAR, PERIOD_NEW : time := 0 ps;
    variable PERIOD_PREVIOUS : time := 0 ps;
    variable Pviol_CLKIN : STD_ULOGIC := '0';
    variable PInfo_CLKIN : VitalPeriodDataType := VitalPeriodDataInit;
    variable CLKCOUNT : integer := 0;
    variable TEMPLINE : LINE ;
    variable PERIOD_CHANGED : BOOLEAN := FALSE;
    begin
        if(TimingChecksOn) then
            VitalPeriodPulseCheck (
                Violation               => Pviol_CLKIN,
                PeriodData              => PInfo_CLKIN,
                TestSignal              => CLKIN_DIV,
                TestSignalName          => "CLKIN",
                TestDelay               => 0 ns,
                Period                  => tperiod_CLKIN_POSEDGE,
                PulseWidthHigh          => tpw_CLKIN_posedge,
                PulseWidthLow           => tpw_CLKIN_negedge,
                CheckEnabled            => TRUE,
                HeaderMsg               => InstancePath &"/X_CLKDLL2",
                Xon                     => Xon,
                MsgOn                   => TRUE,
                MsgSeverity             => WARNING
            );
        end if;

        if (RST_META = '1' ) then
            CLKIN_RISE_PREVIOUS := 0 ps;
            CLKIN_RISE_CURRENT  := 0 ps;
            PERIOD_PREVIOUS     := 0 ps;
            PERIOD_NEW          := 0 ps;
            PERIOD_VAR          := 0 ps;
            PERIOD              <= 0 ps;
            PERIOD_90           <= 0 ps;
            PERIOD_180          <= 0 ps;
            PERIOD_270          <= 0 ps;
            CLKCOUNT            := 0;
            PERIOD_FOUND        <= '0';
        else

            if (CLKIN_DIV'event AND CLKIN_DIV = '1') then
                    CLKIN_RISE_PREVIOUS := CLKIN_RISE_CURRENT;
                    CLKIN_RISE_CURRENT  := NOW;
                    CLKCOUNT := CLKCOUNT + 1;
            end if;

           if (LOCKED_INT = '0' OR (NOADJUST = '0' AND CLKCOUNT >= 100 )) then
            if (CLKIN_RISE_PREVIOUS > 0 ps) then
                PERIOD_FOUND <= '0';
                PERIOD_PREVIOUS := PERIOD_VAR;
                PERIOD_VAR := CLKIN_RISE_CURRENT - CLKIN_RISE_PREVIOUS;

		PERIOD_CHANGED := FALSE;
                if (PERIOD_VAR > PERIOD_PREVIOUS) then
                    if ((PERIOD_VAR - PERIOD_PREVIOUS) < PERIOD_WINDOW_WIDTH) then
                        PERIOD_VAR := PERIOD_PREVIOUS;
		    else
			PERIOD_CHANGED := TRUE;
                    end if;
                elsif (PERIOD_VAR < PERIOD_PREVIOUS) then
                    if ((PERIOD_PREVIOUS - PERIOD_VAR) < PERIOD_WINDOW_WIDTH) then
                        PERIOD_VAR := PERIOD_PREVIOUS;
		    else
			PERIOD_CHANGED := TRUE;
                    end if;
                end if;

                if (TimingChecksOn AND PERIOD_CHANGED AND (PERIOD_VAR > MAXPERCLKIN )) then
                    write(TEMPLINE, STRING'("MAXCLKPERIOD VIOLATION ON CLK;"));

                      write(TEMPLINE, LF );
                      write(TEMPLINE, STRING'("Expected := "));
                      write(TEMPLINE, MAXPERCLKIN );
                      write(TEMPLINE, STRING'( "; Observed := "));
                      write(TEMPLINE, PERIOD_VAR);

                    assert FALSE report
                    TEMPLINE.all & ";"
--                    "*** Warning: Input clock Period is too high *** "
                    severity WARNING;
                    --wait;
                end if;
                PERIOD <= PERIOD_VAR;
                PERIOD_90    <= PERIOD_VAR * 0.25;
                PERIOD_180   <= PERIOD_VAR * 0.5;
                PERIOD_270   <= PERIOD_VAR * 0.75;
                PERIOD_FOUND <= '1';
            end if; -- if CLKINPREVTIME
           end if; -- if NOTLOCKED
        end if; -- if RST

         if (CLKCOUNT >= 100 ) then
            CLKCOUNT := 0;
         end if;

        wait on CLKIN_DIV, RST_META;

    end process DETERMINE_PERIOD;

    CLKLOST_PROC : process (CLK_CHK, CLKIN_DIV)
    variable CLKLOST_INT : std_ulogic := '0';
    variable CLKLOST_i : std_ulogic := '0';
    begin
       if (RST_META = '1' ) then
	   CLKLOST_i := '0';
       else
         if (rising_edge(CLKIN_DIV) = true) then
	    CLKLOST_INT := '0';
	    CLKLOST_i := '0';
         end if;
	 if ( rising_edge(CLK_CHK) = true) then
	   if (CLKLOST_INT = '1' ) then
		CLKLOST_i := '1';
           end if;
	   CLKLOST_INT := '1';
         end if;
	 CLKLOST <= CLKLOST_i;
       end if;
     end process CLKLOST_PROC;
	
    ---------------------------------------------------
    --  Determine Feedback Loop Delay
    ---------------------------------------------------
    DETERMINE_FB_DELAY : process (CLKIN_DIV, CLKFB_ipd, RST_META)
    variable TIME_RISE_CLKIN, TIME_RISE_CLKFB : time := 0 ps;
    variable    PHASEDIFF : time := 100 ps;
    begin
        if (RST_META'event AND RST_META = '1') then
            TIME_RISE_CLKIN := 0 ps;
            TIME_RISE_CLKFB := 0 ps;
            FB_DELAY_FOUND  <= '0';
            NOTINPHASE      <= '0';
            FB_DELAY        <= 0 ps;
        else
             if (CLKIN_DIV'event AND CLKIN_DIV = '1') then
                    TIME_RISE_CLKIN := NOW;
             elsif (CLKFB_ipd'event AND CLKFB_ipd = '1') then
                    TIME_RISE_CLKFB := NOW;
               if ( LOCKED_INT = '1' AND rising_edge(CLKFB_ipd) AND (TIME_RISE_CLKFB - TIME_RISE_CLKIN > PHASEDIFF )) then
               NOTINPHASE <= '1';
               end if;
            end if;

             if (PERIOD_FOUND = '1' AND FB_DELAY_FOUND = '0' AND TIME_RISE_CLKIN /= 0 ns) then
                if (TIME_RISE_CLKFB > TIME_RISE_CLKIN) then
                    FB_DELAY <= TIME_RISE_CLKFB - TIME_RISE_CLKIN;
                    FB_DELAY_FOUND <= '1';
                end if;
            end if;
        end if;
    end process DETERMINE_FB_DELAY;

    ---------------------------------------------------
    --  Set Lock Delay
    ---------------------------------------------------
    SET_LOCK_DELAY : process (PERIOD, CLKIN_DIV, RST_META)
    variable DELAY_AMOUNT : time := 0 ps;
    variable PERIOD_CHANGED : boolean := FALSE;
    begin
        if (RST_META'event AND RST_META = '1') then
            DELAY   <= 0 ps;
            PERIOD_CHANGED := FALSE;
        elsif (PERIOD'event) then
            PERIOD_CHANGED := TRUE;
        end if;
        if (PERIOD_CHANGED AND FB_DELAY_FOUND = '1') then
            DELAY_AMOUNT := PERIOD - FB_DELAY;
            if ((CLKIN_DIV'event AND CLKIN_DIV = '1') AND LOCKED_INT = '0') then
                if (DELAY_AMOUNT - DELAY > DELAY_DELTA) then
                    DELAY <= DELAY + DELAY_DELTA;
                elsif (DELAY - DELAY_AMOUNT > DELAY_DELTA) then
                    DELAY <= DELAY - DELAY_DELTA;
                else
                    DELAY <= DELAY_AMOUNT;
                end if;
            end if;
        end if;
    end process SET_LOCK_DELAY;

    ---------------------------------------------------
    --  Generate Windows
    ---------------------------------------------------
    GENERATE_WINDOWS : process (CLKIN_DIV, CLKFB_ipd, RST_META)
    begin
        if (RST_META'event AND RST_META = '1') then
            CLKIN_WINDOW <= '0';
            CLKFB_WINDOW <= '0';
        else
            if (CLKIN_DIV'event AND CLKIN_DIV = '1') then
                CLKIN_WINDOW <= '1';
                CLKIN_WINDOW <= transport '0' after CLKIN_WINDOW_WIDTH;
            end if;
            if (CLKFB_ipd'event AND CLKFB_ipd = '1') then
                CLKFB_WINDOW <= '1';
                CLKFB_WINDOW <= transport '0' after CLKFB_WINDOW_WIDTH;
            end if;
        end if;
    end process GENERATE_WINDOWS;
 
    WINDOW_OVERLAP <= CLKIN_WINDOW AND CLKFB_WINDOW;
 
    ---------------------------------------------------
    --  Check for a Lock
    ---------------------------------------------------

    DETERMINE_IF_LOCKED : process (CLKIN_DIV, RST_META, WINDOW_OVERLAP)
    variable LOCKED_GlitchData : VitalGlitchDataType;
    variable IS_LOCKED : std_ulogic := '0';
    begin
        if (RST_META'event AND RST_META = '1') then
            LOCKED_INT <= '0';
            IS_LOCKED  := '0';
        elsif (RST_META /= '1' AND (WINDOW_OVERLAP'event AND WINDOW_OVERLAP = '1')) then
            IS_LOCKED := '1';
        elsif (RST_META /= '1' AND (CLKIN_DIV'event AND CLKIN_DIV = '1')) then
            LOCKED_INT<= IS_LOCKED;
            IS_LOCKED := '0';
        end if;
        LOCKED <= LOCKED_INT;

    end process DETERMINE_IF_LOCKED;

    ---------------------------------------------------
    --  Generate CLK_5050 and CLK_2575
    ---------------------------------------------------
    GENERATE_CLOCK_5050_AND_CLK2575 : process (CLKIN_DIV, RST_META)
    begin
        if (RST_META'event AND RST_META = '1') then
            CLK_5050 <= '0';
            CLK_2575 <= '0';
        elsif (PERIOD_FOUND = '1') then
            if (CLKIN_DIV'event AND CLKIN_DIV = '1') then
                CLK_5050 <= '1';
                CLK_2575 <= '1';
                CLK_5050 <= transport '0' after PERIOD_180;
                CLK_2575 <= transport '0' after PERIOD_90;
            end if;
        end if;
    end process GENERATE_CLOCK_5050_AND_CLK2575;
    
    ---------------------------------------------------
    --  Delay CLKIN and CLK_5050 and CLK_2575 for Locking to CLKFB.
    ---------------------------------------------------
    CLKIN_DELAYED_0   <= transport CLKIN_DIV after DELAY;
    CLK5050_DELAYED_0 <= transport CLK_5050  after DELAY;
    CLK2575_DELAYED_0 <= transport CLK_2575  after DELAY;

    ---------------------------------------------------
    --  CLK0, CLK90, CLK180, CLK270, CLK2X and CLK2X90
    ---------------------------------------------------
    DCC <= '1' when DUTY_CYCLE_CORRECTION else '0';
    
 
    CLK_0   <= (PERIOD_FOUND AND (NOT RST_META))  AND
               (((NOT DCC)   AND CLKIN_DELAYED_0)  OR
               (      DCC    AND CLK5050_DELAYED_0));
    CLK0    <= CLK_0;

    CLK90   <= transport CLK_0 after PERIOD_90;
    CLK180  <= transport CLK_0 after PERIOD_180;
    CLK270  <= transport CLK_0 after PERIOD_270;

    CLK5050_DELAYED_90 <= transport CLK_5050 after (DELAY + PERIOD_90);

    CLK_2X  <= (PERIOD_FOUND AND (NOT RST_META)) AND
               (CLK5050_DELAYED_0 XOR CLK5050_DELAYED_90);
    CLK_1X  <= (PERIOD_FOUND AND (NOT RST_META)) AND CLK2575_DELAYED_0;
    CLK2X_INT   <= (LOCKED_INT AND CLK_2X) OR (NOT LOCKED_INT AND CLK_1X);
    CLK2X   <= (LOCKED_INT AND CLK_2X) OR (NOT LOCKED_INT AND CLK_1X);
    CLK2X180 <= transport CLK2X_INT after PERIOD_90;

    ---------------------------------------------------
    --  Clock Divider
    ---------------------------------------------------
    GENERATE_CLOCK_DIV : process (CLK2X_INT, RST_META)
    variable FIRST_TIME      : boolean    := TRUE;
    variable COUNT_RISE_FALL : real       := 0.0;
    variable CLOCK_DIV       : std_ulogic := '0';
    begin
        if (RST_META = '1') then
            FIRST_TIME      := TRUE;
            COUNT_RISE_FALL := 0.0;
            CLOCK_DIV       := '0';
        elsif (PERIOD_FOUND = '1') then
            if (CLK2X_INT'event AND LOCKED_INT = '1') then
                if (CLK2X_INT = '1') then
                    if (FIRST_TIME) then
                        CLOCK_DIV  := NOT CLOCK_DIV;
                        FIRST_TIME := FALSE;
                    else COUNT_RISE_FALL := COUNT_RISE_FALL + 1.0;
                    end if;
                end if;
                if (CLK2X_INT = '0' AND IS_FRACTIONAL) then
                    COUNT_RISE_FALL := COUNT_RISE_FALL + 1.0;
                end if;
                if (COUNT_RISE_FALL >= DIVISOR) then
                    CLOCK_DIV       := NOT CLOCK_DIV;
                    COUNT_RISE_FALL := 0.0;
                end if;
            end if;
            CLKDV <= CLOCK_DIV;
        end if;
    end process GENERATE_CLOCK_DIV;
end X_CLKDLL2_V;

configuration CFG_X_CLKDLL2_V of X_CLKDLL2 is
    for X_CLKDLL2_V
    end for;
end CFG_X_CLKDLL2_V;
----- CELL X_FF -----
library IEEE;
use IEEE.STD_LOGIC_1164.all;
library IEEE;
use IEEE.VITAL_Timing.all;


-- entity declaration --
entity X_FF is
   generic(
      TimingChecksOn: Boolean := True;
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_SET_O                      :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_RST_O                      :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_CLK_O                      :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tsetup_I_CLK_posedge_posedge   :	VitalDelayType := 0.010 ns;
      tsetup_I_CLK_negedge_posedge   :	VitalDelayType := 0.010 ns;
      thold_I_CLK_posedge_posedge    :	VitalDelayType := 0.010 ns;
      thold_I_CLK_negedge_posedge    :	VitalDelayType := 0.010 ns;
      tsetup_CE_CLK_posedge_posedge  :	VitalDelayType := 0.010 ns;
      tsetup_CE_CLK_negedge_posedge  :	VitalDelayType := 0.010 ns;
      thold_CE_CLK_posedge_posedge   :	VitalDelayType := 0.010 ns;
      thold_CE_CLK_negedge_posedge   :	VitalDelayType := 0.010 ns;
      trecovery_RST_CLK_negedge_posedge :	VitalDelayType := 0.010 ns;
      thold_RST_CLK_negedge_posedge  :	VitalDelayType := 0.010 ns;
      trecovery_SET_CLK_negedge_posedge :	VitalDelayType := 0.010 ns;
      thold_SET_CLK_negedge_posedge  :	VitalDelayType := 0.010 ns;
      tpw_CLK_posedge                :	VitalDelayType := 0.010 ns;
      tpw_RST_posedge                :	VitalDelayType := 0.010 ns;
      tpw_SET_posedge                :	VitalDelayType := 0.010 ns;
      tpw_CLK_negedge                :	VitalDelayType := 0.010 ns;
      tipd_I                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_CLK                       :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_CE                        :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_RST                       :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_SET                       :	VitalDelayType01 := (0.000 ns, 0.000 ns));

   port(
      O                              :	out   STD_ULOGIC;
      I                              :	in    STD_ULOGIC;
      CLK                            :	in    STD_ULOGIC;
      CE                             :	in    STD_ULOGIC;
      RST                            :	in    STD_ULOGIC;
      SET                            :	in    STD_ULOGIC);
attribute VITAL_LEVEL0 of X_FF : entity is TRUE;
end X_FF;

-- architecture body --
library IEEE;
use IEEE.VITAL_Primitives.all;
library simprim;
use simprim.VPACKAGE.all;
architecture X_FF_V of X_FF is
   attribute VITAL_LEVEL1 of X_FF_V : architecture is TRUE;

   SIGNAL I_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CLK_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CE_ipd	 : STD_ULOGIC := 'X';
   SIGNAL RST_ipd	 : STD_ULOGIC := 'X';
   SIGNAL SET_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (I_ipd, I, tipd_I);
   VitalWireDelay (CLK_ipd, CLK, tipd_CLK);
   VitalWireDelay (CE_ipd, CE, tipd_CE);
   VitalWireDelay (RST_ipd, RST, tipd_RST);
   VitalWireDelay (SET_ipd, SET, tipd_SET);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process (I_ipd, CLK_ipd, CE_ipd, RST_ipd, SET_ipd)

   -- timing check results
   VARIABLE Tviol_I_CLK_posedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_I_CLK_posedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Tviol_CE_CLK_posedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_CE_CLK_posedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Tviol_RST_CLK_posedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_RST_CLK_posedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Tviol_SET_CLK_posedge	: STD_ULOGIC := '0';
   VARIABLE Tmkr_SET_CLK_posedge	: VitalTimingDataType := VitalTimingDataInit;
   VARIABLE Pviol_CLK	: STD_ULOGIC := '0';
   VARIABLE PInfo_CLK	: VitalPeriodDataType := VitalPeriodDataInit;
   VARIABLE Pviol_RST	: STD_ULOGIC := '0';
   VARIABLE PInfo_RST	: VitalPeriodDataType := VitalPeriodDataInit;
   VARIABLE Pviol_SET	: STD_ULOGIC := '0';
   VARIABLE PInfo_SET	: VitalPeriodDataType := VitalPeriodDataInit;

   -- functionality results
   VARIABLE Violation : STD_ULOGIC := '0';
   VARIABLE PrevData_O : STD_LOGIC_VECTOR(0 to 6);
   VARIABLE I_delayed : STD_ULOGIC := 'X';
   VARIABLE CLK_delayed : STD_ULOGIC := 'X';
   VARIABLE CE_delayed : STD_ULOGIC := 'X';
   VARIABLE Results : STD_LOGIC_VECTOR(1 to 1) := (others => 'X');
   ALIAS O_zd : STD_LOGIC is Results(1);

   -- output glitch detection variables
   VARIABLE O_GlitchData	: VitalGlitchDataType;

   begin

      ------------------------
      --  Timing Check Section
      ------------------------
      if (TimingChecksOn) then
         VitalSetupHoldCheck (
          Violation               => Tviol_I_CLK_posedge,
          TimingData              => Tmkr_I_CLK_posedge,
          TestSignal              => I_ipd,
          TestSignalName          => "I",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName          => "CLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_I_CLK_posedge_posedge,
          SetupLow                => tsetup_I_CLK_negedge_posedge,
          HoldLow                => thold_I_CLK_posedge_posedge,
          HoldHigh                 => thold_I_CLK_negedge_posedge,
          CheckEnabled            => TO_X01(((NOT RST_ipd)) AND (CE_ipd)
                                     AND ((NOT SET_ipd))) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_FF",
          Xon                     => Xon,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
         VitalSetupHoldCheck (
          Violation               => Tviol_CE_CLK_posedge,
          TimingData              => Tmkr_CE_CLK_posedge,
          TestSignal              => CE_ipd,
          TestSignalName          => "CE",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName          => "CLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_CE_CLK_posedge_posedge,
          SetupLow                => tsetup_CE_CLK_negedge_posedge,
          HoldLow                => thold_CE_CLK_posedge_posedge,
          HoldHigh                 => thold_CE_CLK_negedge_posedge,
          CheckEnabled            => TO_X01(((NOT RST_ipd)) AND ((O_zd) XOR (I_ipd)) AND ((NOT SET_ipd))) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_FF",
          Xon                     => Xon,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
         VitalRecoveryRemovalCheck (
          Violation               => Tviol_RST_CLK_posedge,
          TimingData              => Tmkr_RST_CLK_posedge,
          TestSignal              => RST_ipd,
          TestSignalName          => "RST",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName          => "CLK",
          RefDelay                => 0 ns,
          Recovery                => trecovery_RST_CLK_negedge_posedge,
          Removal                 => thold_RST_CLK_negedge_posedge,
          ActiveLow               => FALSE,
          CheckEnabled            => TO_X01(CE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_FF",
          Xon                     => Xon,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
         VitalRecoveryRemovalCheck (
          Violation               => Tviol_SET_CLK_posedge,
          TimingData              => Tmkr_SET_CLK_posedge,
          TestSignal              => SET_ipd,
          TestSignalName          => "SET",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName          => "CLK",
          RefDelay                => 0 ns,
          Recovery                => trecovery_SET_CLK_negedge_posedge,
          Removal                 => thold_SET_CLK_negedge_posedge,
          ActiveLow               => FALSE,
          CheckEnabled            => TO_X01((NOT RST_ipd) AND CE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_FF",
          Xon                     => Xon,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_CLK,
          PeriodData              => PInfo_CLK,
          TestSignal              => CLK_ipd,
          TestSignalName          => "CLK",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLK_posedge,
          PulseWidthLow           => tpw_CLK_negedge,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/X_FF",
          Xon                     => Xon,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_RST,
          PeriodData              => PInfo_RST,
          TestSignal              => RST_ipd,
          TestSignalName          => "RST",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_RST_posedge,
          PulseWidthLow           => 0 ns,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/X_FF",
          Xon                     => Xon,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_SET,
          PeriodData              => PInfo_SET,
          TestSignal              => SET_ipd,
          TestSignalName          => "SET",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_SET_posedge,
          PulseWidthLow           => 0 ns,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/X_FF",
          Xon                     => Xon,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
      end if;

      -------------------------
      --  Functionality Section
      -------------------------
      Violation := Tviol_I_CLK_posedge or Pviol_RST or 
                   Tviol_CE_CLK_posedge or Tviol_RST_CLK_posedge or
                   Tviol_SET_CLK_posedge or Pviol_SET or Pviol_CLK;
      VitalStateTable(
        Result => O_zd,
        PreviousDataIn => PrevData_O,
        StateTable => X_FF_O_tab,
        DataIn => (CLK_DELAYED, SET_ipd, O_zd, I_delayed, CE_delayed, CLK_ipd, RST_ipd));
      O_zd := Violation XOR O_zd;
      I_delayed := I_ipd;
      CLK_delayed := CLK_ipd;
      CE_delayed := CE_ipd;

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => O,
       GlitchData => O_GlitchData,
       OutSignalName => "O",
       OutTemp => O_zd,
       Paths => (0 => (CLK_ipd'last_event, tpd_CLK_O, (CE_ipd /= '0' AND RST_ipd /= '1' AND SET_ipd /= '1')),
                 1 => (SET_ipd'last_event, tpd_SET_O, (RST_ipd /= '1')),
                 2 => (RST_ipd'last_event, tpd_RST_O, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

end process;

end X_FF_V;

configuration CFG_X_FF_V of X_FF is
   for X_FF_V
   end for;
end CFG_X_FF_V;
----- CELL X_IBUFDS -----
library IEEE;
use IEEE.STD_LOGIC_1164.all;
library IEEE;
use IEEE.VITAL_Timing.all;


-- entity declaration --
entity X_IBUFDS is
   generic(
      TimingChecksOn: Boolean := TRUE;
      InstancePath: STRING := "*";
      Xon: Boolean := True;
      MsgOn: Boolean := False;
      tpd_I_O                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tpd_IB_O                        :	VitalDelayType01 := (0.100 ns, 0.100 ns);
      tipd_IB                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_I                         :	VitalDelayType01 := (0.000 ns, 0.000 ns));

   port(
      O                              :	out   STD_ULOGIC;
      I                              :	in    STD_ULOGIC;
      IB                             :	in    STD_ULOGIC);
attribute VITAL_LEVEL0 of X_IBUFDS : entity is TRUE;
end X_IBUFDS;

-- architecture body --
library IEEE;
use IEEE.VITAL_Primitives.all;
library SIMPRIM;
use SIMPRIM.VPACKAGE.all;
architecture X_IBUFDS_V of X_IBUFDS is
--   attribute VITAL_LEVEL1 of X_IBUFDS_V : architecture is TRUE;

   SIGNAL I_ipd	 : STD_ULOGIC := 'X';
   SIGNAL IB_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (I_ipd, I, tipd_I);
   VitalWireDelay (IB_ipd, IB, tipd_IB);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VitalBehavior : process (I_ipd, IB_ipd)


   -- functionality results
   VARIABLE Results : STD_LOGIC_VECTOR(1 to 1) := (others => 'X');
   ALIAS O_zd : STD_LOGIC is Results(1);

   -- output glitch detection variables
   VARIABLE O_GlitchData	: VitalGlitchDataType;

   begin

      -------------------------
      --  Functionality Section
      -------------------------
      if (I_ipd /= IB_ipd ) then 
      O_zd := TO_X01(I_ipd);
      else
      O_zd := 'X';
      end if;

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => O,
       GlitchData => O_GlitchData,
       OutSignalName => "O",
       OutTemp => O_zd,
       Paths => (0 => (I_ipd'last_event, tpd_I_O, TRUE),
		 1 => (IB_ipd'last_event, tpd_IB_O, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

end process;

end X_IBUFDS_V;

configuration CFG_X_IBUFDS_V of X_IBUFDS is
   for X_IBUFDS_V
   end for;
end CFG_X_IBUFDS_V;
