          HoldHigh                => thold_GE_CLK_posedge_negedge,
          HoldLow                 => thold_GE_CLK_negedge_negedge,
          CheckEnabled            => TO_X01(((NOT RST_ipd)) AND ((O_zd) XOR (I_ipd))
                                     AND ((NOT SET_ipd))) /= '0',
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/X_LATCHE",
          Xon                     => Xon,
          MsgOn                   => TRUE,
