          TestSignalName          => "SET",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName          => "CLK",
          RefDelay                => 0 ns,
          Recovery                => trecovery_SET_CLK_negedge_negedge,
          Removal                 => thold_SET_CLK_negedge_negedge,
          ActiveLow               => FALSE,
          CheckEnabled            => TO_X01(((NOT RST_ipd)) AND (GE_ipd)) /= '0',
          RefTransition           => 'F',
          HeaderMsg               => InstancePath & "/X_LATCHE",
          Xon                     => Xon,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_CLK,
          PeriodData              => PInfo_CLK,
          TestSignal              => CLK_ipd,
          TestSignalName          => "CLK",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLK_posedge,
          PulseWidthLow           => tpw_CLK_negedge,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/X_LATCHE",
          Xon                     => Xon,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_RST,
          PeriodData              => PInfo_RST,
          TestSignal              => RST_ipd,
          TestSignalName          => "RST",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_RST_posedge,
          PulseWidthLow           => 0 ns,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/X_LATCHE",
          Xon                     => Xon,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
         VitalPeriodPulseCheck (
          Violation               => Pviol_SET,
          PeriodData              => PInfo_SET,
          TestSignal              => SET_ipd,
          TestSignalName          => "SET",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_SET_posedge,
          PulseWidthLow           => 0 ns,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/X_LATCHE",
          Xon                     => Xon,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
      end if;

      -------------------------
      --  Functionality Section
      -------------------------
      Violation := Tviol_I_CLK_negedge or Tviol_GE_CLK_negedge or
                   Tviol_SET_CLK_negedge or Pviol_RST or Pviol_SET or
                   Tviol_RST_CLK_negedge or Pviol_CLK;
      VitalStateTable(
        Result => O_zd,
        PreviousDataIn => PrevData_O,
        StateTable => X_LATCHE_O_tab,
        DataIn => (SET_ipd, O_zd, I_ipd, GE_ipd, CLK_ipd, RST_ipd));
      O_zd := Violation XOR O_zd;

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => O,
       GlitchData => O_GlitchData,
       OutSignalName => "O",
       OutTemp => O_zd,
       Paths => (0 => (I_ipd'last_event, tpd_I_O, (CLK_ipd /= '0' AND GE_ipd /= '0' 
                       AND RST_ipd /= '1' AND SET_ipd /= '1')),
                 1 => (CLK_ipd'last_event, tpd_CLK_O, (GE_ipd /= '0' AND RST_ipd /= '1' AND SET_ipd /= '1')),
                 2 => (GE_ipd'last_event, tpd_GE_O, (CLK_ipd /= '0' AND RST_ipd /= '1' AND SET_ipd /= '1')),
                 3 => (SET_ipd'last_event, tpd_SET_O, (RST_ipd /= '1')),
                 4 => (RST_ipd'last_event, tpd_RST_O, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

end process;

end X_LATCHE_V;

