      tipd_I1                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_CLK0                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_CLK1                         :	VitalDelayType01 := (0.000 ns, 0.000 ns);
      tipd_CE                        :	VitalDelayType01 := (0.000 ns, 0.000 ns));

   port(
      O                             :	out   STD_ULOGIC;
      I0                              :	in    STD_ULOGIC;
      I1                              :	in    STD_ULOGIC;
      CLK0                             :	in    STD_ULOGIC;
      CLK1                             :	in    STD_ULOGIC;
      CE                             :	in    STD_ULOGIC);
attribute VITAL_LEVEL0 of X_MUXDDR : entity is TRUE;
end X_MUXDDR;

-- architecture body --
library IEEE;
use IEEE.VITAL_Primitives.all;
library SIMPRIM;
use SIMPRIM.VPACKAGE.all;
architecture X_MUXDDR_V of X_MUXDDR is
--   attribute VITAL_LEVEL1 of X_MUXDDR_V : architecture is TRUE;

   SIGNAL I0_ipd	 : STD_ULOGIC := 'X';
   SIGNAL I1_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CLK0_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CLK1_ipd	 : STD_ULOGIC := 'X';
   SIGNAL CE_ipd	 : STD_ULOGIC := 'X';

begin

   ---------------------
   --  INPUT PATH DELAYs
   ---------------------
   WireDelay : block
   begin
   VitalWireDelay (I0_ipd, I0, tipd_I0);
   VitalWireDelay (I1_ipd, I1, tipd_I1);
   VitalWireDelay (CLK0_ipd, CLK0, tipd_CLK0);
   VitalWireDelay (CLK1_ipd, CLK1, tipd_CLK1);
   VitalWireDelay (CE_ipd, CE, tipd_CE);
   end block;
   --------------------
   --  BEHAVIOR SECTION
   --------------------
   VITALBehavior : process (CLK0_ipd, CLK1_ipd, I0_ipd, I1_ipd )

   -- timing check results

   -- functionality results
   VARIABLE Results : STD_LOGIC_VECTOR(1 to 1) := (others => 'X');
   ALIAS O_zd : STD_LOGIC is Results(1);
   VARIABLE S_ipd	 : STD_ULOGIC := '0';

   -- output glitch detection variables
   VARIABLE O_GlitchData	: VitalGlitchDataType;

   begin

      -------------------------
      --  Functionality Section
      -------------------------
 
      If ( rising_edge(CLK0_ipd) = TRUE) then
		if (CE_ipd = '1' ) then
 			O_zd := I0_ipd;
			S_ipd := '0';
		end if;
      elsif (rising_edge(CLK1_ipd) = TRUE ) then
		if (CE_ipd = '1') then
 			O_zd := I1_ipd;
			S_ipd := '1';
		end if;
      elsif (I0_ipd'event AND S_ipd = '0' ) then
		O_zd := I0_ipd;
      elsif (I1_ipd'event AND S_ipd = '1' ) then
		O_zd := I1_ipd;
      end if;

      ----------------------
      --  Path Delay Section
      ----------------------
      VitalPathDelay01 (
       OutSignal => O,
       GlitchData => O_GlitchData,
       OutSignalName => "O",
       OutTemp => O_zd,
       Paths => (0 => (CLK0_ipd'last_event, tpd_CLK0_O, TRUE),
                 1 => (CLK1_ipd'last_event, tpd_CLK1_O, TRUE),
                 2 => (I0_ipd'last_event, tpd_I0_O, TRUE),
                 3 => (I1_ipd'last_event, tpd_I1_O, TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING);

end process VITALBehavior;

end X_MUXDDR_V;

