   VARIABLE OB_GlitchData	: VitalGlitchDataType;

   begin

      -------------------------
      --  Functionality Section
      -------------------------
      O_zd := VitalBUFIF0 (data => I_ipd,
              enable => T_ipd);
      OB_zd := VitalBUFIF0 (data => NOT I_ipd,
