       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING,
       OutputMap => "UX01ZWLH-");
      VitalPathDelay01Z (
       OutSignal => OB,
       GlitchData => OB_GlitchData,
       OutSignalName => "OB",
       OutTemp => OB_zd,
       Paths => (0 => (I_ipd'last_event, VitalExtendToFillDelay(tpd_I_OB), TRUE),
                 1 => (T_ipd'last_event, VitalExtendToFillDelay(tpd_T_OB), TRUE)),
       Mode => OnEvent,
       Xon => Xon,
       MsgOn => MsgOn,
       MsgSeverity => WARNING,
       OutputMap => "UX01ZWLH-");

end process;

end X_OBUFTDS_V;

