          Xon                     => TRUE,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
      end if;
    --
    -- Port A
    --
    WR_A_LATER := FALSE;
    WR_B_LATER := FALSE;

    if (GSR_ipd = '1') then
        DOA_zd := INI_A ( 15 downto 0);
        DOPA_zd := INI_A ( 17 downto 16);
    elsif (GSR_ipd = '0') then
        if (ENA_ipd = '1') then
            if (CLKA_ipd'event AND CLKA_ipd'last_value = '0') then
                if (CLKA_ipd = '1') then
                    if (WEA_ipd = '1') then
                        if (VALID_ADDRA) then
                            if(WRITE_MODE_A = "WRITE_FIRST") then
                              DOA_zd := DIA_ipd;
                              DOPA_zd := DIPA_ipd;
                            elsif(WRITE_MODE_A = "READ_FIRST") then
                              DOA_zd := MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW));
                              DOPA_zd := MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW));
                            elsif(WRITE_MODE_A /= "NO_CHANGE") then
                              assert false report
                              " Wrong value for write_mode, assuming WRITE_FIRST "
                              severity warning;
                              DOA_zd := DIA_ipd;
                              DOPA_zd := DIPA_ipd;
                            end if;
                            if (WRITE_MODE_A /= "READ_FIRST" ) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := DIA_ipd;
                            MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := DIPA_ipd;
                            else WR_A_LATER := TRUE;
                            end if;
                            if (ENB_ipd = '1' AND VALID_ADDRB AND HAS_OVERLAP) then
                                if (Tviol_CLKB_CLKA_posedge = 'X') then
                                    if (WEB_ipd /= '0') then
                                      if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "READ_FIRST") then
                                        COLLISION (ADDRA_ipd, OLP_LSB, OLP_MSB, "write", 
                                        "port A", "port B", InstancePath, MEM);
                                        COLLISION (ADDRA_ipd, OLPP_LSB, OLPP_MSB, "write", 
                                        "port A", "port B", InstancePath, MEMP);
                                      end if;
                                      if (WRITE_MODE_A /= "NO_CHANGE" AND WRITE_MODE_B/= "READ_FIRST" ) then
                                        DOA_zd (DOA_OV_MSB downto DOA_OV_LSB) := (others =>'X');
                                        DOPA_zd (DOPA_OV_MSB downto DOPA_OV_LSB) := (others =>'X');
                                      end if;
                                      if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "NO_CHANGE" ) then
                                        DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others =>'X');
                                        DOPB_zd (DOPB_OV_MSB downto DOPB_OV_LSB) := (others =>'X');
				      end if;
                                    else
                                      if (WRITE_MODE_A /= "READ_FIRST" ) then
                                        COLLISION (ADDRA_ipd, OLP_LSB, OLP_MSB, "read",
                                        "port A", "port B", InstancePath, MEM);
                                        COLLISION (ADDRA_ipd, OLPP_LSB, OLPP_MSB, "read",
                                        "port A", "port B", InstancePath, MEMP);
                                        DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others =>'X');
                                        DOPB_zd (DOPB_OV_MSB downto DOPB_OV_LSB) := (others =>'X');
				      end if;
                                    end if;
                                end if;
                            end if;
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                            SET_MEM_TO_X(ADDRA_ipd, MEMP);
                            if (WRITE_MODE_A /= "NO_CHANGE") then
                            DOA_zd := (others => 'X');
                            DOPA_zd := (others => 'X');
			    end if;
                        end if;
                    elsif (WEA_ipd = 'X') then
                        if (VALID_ADDRA) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                            MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                            SET_MEM_TO_X(ADDRA_ipd, MEMP);
                        end if;
                        DOA_zd := (others => 'X');
                        DOPA_zd := (others => 'X');
                    else 
                        if (VALID_ADDRA) then
                            DOA_zd := MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW));
                            DOPA_zd := MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW));
                        else
                            DOA_zd := (others => 'X');
                            DOPA_zd := (others => 'X');
                        end if;
                    end if;
                    if (SSRA_ipd = '1') then
                        DOA_zd := SRVA_A (15 downto 0);
                        DOPA_zd := SRVA_A (17 downto 16);
                    elsif (SSRA_ipd = 'X') then
                        DOA_zd := (others => 'X');
                        DOPA_zd := (others => 'X');
                    end if;
                elsif (CLKA_ipd = 'X') then
                    if (WEA_ipd /= '0') then
                        if (VALID_ADDRA) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                            MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                            SET_MEM_TO_X(ADDRA_ipd, MEMP);
                        end if;
                    end if;
                    if (WRITE_MODE_A /= "NO_CHANGE" ) then
                    DOA_zd := (others => 'X');
                    DOPA_zd := (others => 'X');
		    end if;
                end if; 
            elsif (CLKA_ipd'event AND CLKA_ipd'last_value = 'X') then
                if (CLKA_ipd = '1') then
                    if (WEA_ipd /= '0') then
                        if (VALID_ADDRA) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                            MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                            SET_MEM_TO_X(ADDRA_ipd, MEMP);
                        end if;
                    end if;
                    DOA_zd := (others => 'X');
                    DOPA_zd := (others => 'X');
                end if;
            end if; 
        elsif (ENA_ipd = 'X') then
            if (CLKA_ipd'event AND CLKA_ipd'last_value /= '1') then
                if (CLKA_ipd /= '0') then
                    if (WEA_ipd /= '0') then
                        if (VALID_ADDRA) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                            MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                            SET_MEM_TO_X(ADDRA_ipd, MEMP);
                            MEM := (others => 'X');
                            MEMP := (others => 'X');
                        end if;
                    end if;
                    DOA_zd := (others => 'X');
                    DOPA_zd := (others => 'X');
                end if;
            end if; 
        end if; 
    else
        DOA_zd := (others => 'X');
        DOPA_zd := (others => 'X');
    end if; 
    
    --
    -- Port B
    --
    if (GSR_ipd = '1') then
        DOB_zd :=  INI_B (31 downto 0);
        DOPB_zd := INI_B (35 downto 32);
    elsif (GSR_ipd = '0') then
        if (ENB_ipd = '1') then
            if (CLKB_ipd'event AND CLKB_ipd'last_value = '0') then
                if (CLKB_ipd = '1') then
                    if (WEB_ipd = '1') then
                        if (VALID_ADDRB) then
                           if(WRITE_MODE_B = "WRITE_FIRST") then
                             DOB_zd := DIB_ipd;
                             DOPB_zd := DIPB_ipd;
                           elsif(WRITE_MODE_B = "READ_FIRST") then
                             DOB_zd := MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW))
;
                             DOPB_zd :=MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) ;
                          elsif(WRITE_MODE_B /= "NO_CHANGE") then
