          HoldLow                => thold_ADDRB_CLKB_posedge_posedge(6),
          HoldHigh                 => thold_ADDRB_CLKB_negedge_posedge(6),
          CheckEnabled            => TO_X01(ENB_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB16_S1_S1",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
