          HeaderMsg               => InstancePath & "/X_RAMB16_S1_S1",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_ADDRB2_CLKB_posedge,
          TimingData              => Tmkr_ADDRB2_CLKB_posedge,
          TestSignal              => ADDRB_ipd(2),
          TestSignalName          => "ADDRB(2)",
          TestDelay               => 0 ns,
          RefSignal               => CLKB_ipd,
          RefSignalName           => "CLKB",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_ADDRB_CLKB_posedge_posedge(2),
          SetupLow                => tsetup_ADDRB_CLKB_negedge_posedge(2),
          HoldLow                => thold_ADDRB_CLKB_posedge_posedge(2),
          HoldHigh                 => thold_ADDRB_CLKB_negedge_posedge(2),
          CheckEnabled            => TO_X01(ENB_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB16_S1_S1",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_ADDRB1_CLKB_posedge,
          TimingData              => Tmkr_ADDRB1_CLKB_posedge,
          TestSignal              => ADDRB_ipd(1),
          TestSignalName          => "ADDRB(1)",
          TestDelay               => 0 ns,
          RefSignal               => CLKB_ipd,
          RefSignalName           => "CLKB",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_ADDRB_CLKB_posedge_posedge(1),
          SetupLow                => tsetup_ADDRB_CLKB_negedge_posedge(1),
          HoldLow                => thold_ADDRB_CLKB_posedge_posedge(1),
          HoldHigh                 => thold_ADDRB_CLKB_negedge_posedge(1),
          CheckEnabled            => TO_X01(ENB_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB16_S1_S1",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_ADDRB0_CLKB_posedge,
          TimingData              => Tmkr_ADDRB0_CLKB_posedge,
          TestSignal              => ADDRB_ipd(0),
          TestSignalName          => "ADDRB(0)",
          TestDelay               => 0 ns,
          RefSignal               => CLKB_ipd,
          RefSignalName           => "CLKB",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_ADDRB_CLKB_posedge_posedge(0),
          SetupLow                => tsetup_ADDRB_CLKB_negedge_posedge(0),
          HoldLow                => thold_ADDRB_CLKB_posedge_posedge(0),
          HoldHigh                 => thold_ADDRB_CLKB_negedge_posedge(0),
          CheckEnabled            => TO_X01(ENB_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB16_S1_S1",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck (
          Violation               => Pviol_CLKA,
          PeriodData              => PInfo_CLKA,
          TestSignal              => CLKA_ipd,
          TestSignalName          => "CLKA",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLKA_posedge,
          PulseWidthLow           => tpw_CLKA_negedge,
          CheckEnabled            => TO_X01(ENA_ipd) /= '0',
          HeaderMsg               => InstancePath &"/X_RAMB16_S1_S1",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck (
          Violation               => Pviol_CLKB,
          PeriodData              => PInfo_CLKB,
          TestSignal              => CLKB_ipd,
          TestSignalName          => "CLKB",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLKB_posedge,
          PulseWidthLow           => tpw_CLKB_negedge,
          CheckEnabled            => TO_X01(ENB_ipd) /= '0',
          HeaderMsg               => InstancePath &"/X_RAMB16_S1_S1",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck ( 
          Violation               => Pviol_GSR,
          PeriodData              => PInfo_GSR,
          TestSignal              => GSR_ipd,
          TestSignalName          => "GSR",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_GSR_posedge,
          PulseWidthLow           => 0 ns,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/X_RAMB16_S1_S1",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);
 
    end if;

    Violation := 
                 Tviol_DIA0_CLKA_posedge   or

                 Tviol_ENA_CLKA_posedge    or Tviol_WEA_CLKA_posedge    or
                 Tviol_SSRA_CLKA_posedge   or Tviol_ADDRA12_CLKA_posedge or

		 Tviol_ADDRA13_CLKA_posedge or
                 Tviol_ADDRA11_CLKA_posedge or Tviol_ADDRA10_CLKA_posedge or
                 Tviol_ADDRA9_CLKA_posedge or Tviol_ADDRA8_CLKA_posedge or
                 Tviol_ADDRA7_CLKA_posedge or Tviol_ADDRA6_CLKA_posedge or
                 Tviol_ADDRA5_CLKA_posedge or Tviol_ADDRA4_CLKA_posedge or 
                 Tviol_ADDRA3_CLKA_posedge or Tviol_ADDRA2_CLKA_posedge or 
                 Tviol_ADDRA1_CLKA_posedge or Tviol_ADDRA0_CLKA_posedge or 

                 Pviol_CLKA                or

                 Tviol_DIB0_CLKB_posedge   or

                 Tviol_ENB_CLKB_posedge    or Tviol_WEB_CLKB_posedge    or
                 Tviol_SSRB_CLKB_posedge   or 
                 Tviol_ADDRB13_CLKB_posedge or  Tviol_ADDRB12_CLKB_posedge or
                 Tviol_ADDRB11_CLKB_posedge or Tviol_ADDRB10_CLKB_posedge or
                 Tviol_ADDRB9_CLKB_posedge or Tviol_ADDRB8_CLKB_posedge or
                 Tviol_ADDRB7_CLKB_posedge or Tviol_ADDRB6_CLKB_posedge or
                 Tviol_ADDRB5_CLKB_posedge or Tviol_ADDRB4_CLKB_posedge or
                 Tviol_ADDRB3_CLKB_posedge or Tviol_ADDRB2_CLKB_posedge or
                 Tviol_ADDRB1_CLKB_posedge or Tviol_ADDRB0_CLKB_posedge or 

                 Pviol_CLKB;

    -------------------------
    --  Functionality Section
    -------------------------

    VALID_ADDRA := ADDR_IS_VALID(ADDRA_ipd);
    VALID_ADDRB := ADDR_IS_VALID(ADDRB_ipd);

    if (VALID_ADDRA) then
        ADDRESS_A := SLV_TO_INT(ADDRA_ipd);
    end if;

    if (VALID_ADDRB) then
        ADDRESS_B := SLV_TO_INT(ADDRB_ipd);
    end if;

    if (VALID_ADDRA AND VALID_ADDRB) then
        ADDR_OVERLAP (ADDRESS_A, ADDRESS_B, DIAW, DIBW, HAS_OVERLAP, 
        OLP_LSB, OLP_MSB, DOA_OV_LSB, DOA_OV_MSB, DOB_OV_LSB, DOB_OV_MSB);
    end if;

     if (TimingChecksOn AND HAS_OVERLAP = TRUE ) then 
         VitalSetupHoldCheck (
          Violation               => Tviol_CLKB_CLKA_posedge,
          TimingData              => Tmkr_CLKB_CLKA_posedge,
          TestSignal              => CLKB_ipd,
          TestSignalName          => "CLKB",
          TestDelay               => 0 ns,
          RefSignal               => CLKA_ipd,
          RefSignalName           => "CLKA",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_CLKB_CLKA_posedge_posedge,
          CheckEnabled            => TO_X01(ENA_ipd AND ENB_ipd AND (WEA_ipd OR WEB_ipd)) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB16_S1_S1",
          Xon                     => TRUE,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck ( 
          Violation               => Tviol_CLKA_CLKB_posedge, 
          TimingData              => Tmkr_CLKA_CLKB_posedge, 
          TestSignal              => CLKA_ipd, 
          TestSignalName          => "CLKA", 
          TestDelay               => 0 ns, 
          RefSignal               => CLKB_ipd, 
          RefSignalName           => "CLKB", 
          RefDelay                => 0 ns, 
          SetupHigh               => tsetup_CLKA_CLKB_posedge_posedge, 
          CheckEnabled            => TO_X01(ENA_ipd AND ENB_ipd AND (WEA_ipd OR WEB_ipd)) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB16_S1_S1",
          Xon                     => TRUE,
          MsgOn                   => TRUE,
          MsgSeverity             => WARNING);
      end if;
    --
    -- Port A
    --
    WR_A_LATER := FALSE;
    WR_B_LATER := FALSE;

    if (GSR_ipd = '1') then
        DOA_zd := INI_A(0 downto 0) ;
    elsif (GSR_ipd = '0') then
        if (ENA_ipd = '1') then
            if (CLKA_ipd'event AND CLKA_ipd'last_value = '0') then
                if (CLKA_ipd = '1') then
                    if (WEA_ipd = '1') then
                        if (VALID_ADDRA) then
                            if(WRITE_MODE_A = "WRITE_FIRST") then
                              DOA_zd := DIA_ipd;
                            elsif(WRITE_MODE_A = "READ_FIRST") then
                              DOA_zd := MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW));
                            elsif(WRITE_MODE_A /= "NO_CHANGE") then
                              assert false report
                              " Wrong value for write_mode, assuming WRITE_FIRST"
                              severity warning;
                              DOA_zd := DIA_ipd;
                            end if;
                            if (WRITE_MODE_A /= "READ_FIRST" ) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := DIA_ipd;
                            else WR_A_LATER := TRUE;
                            end if;

                            if (ENB_ipd = '1' AND VALID_ADDRB AND HAS_OVERLAP) then
                                if (Tviol_CLKB_CLKA_posedge = 'X') then
                                    if (WEB_ipd /= '0') then
                                      if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "READ_FIRST") then
                                        COLLISION (ADDRA_ipd, OLP_LSB, OLP_MSB, "write", 
                                        "port A", "port B", InstancePath, MEM);
                                      end if;
                                      if (WRITE_MODE_A /= "NO_CHANGE" AND WRITE_MODE_B/= "READ_FIRST" ) then
                                        DOA_zd (DOA_OV_MSB downto DOA_OV_LSB) := (others =>'X');
                                      end if;
                                      if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "NO_CHANGE" ) then
                                        DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others =>'X');
				      end if;
                                    else
                                      if (WRITE_MODE_A /= "READ_FIRST" ) then
                                        COLLISION (ADDRA_ipd, OLP_LSB, OLP_MSB, "read",
                                        "port A", "port B", InstancePath, MEM);
                                        DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others =>'X');
				      end if;
                                    end if;
                                end if;
                            end if;
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                            if (WRITE_MODE_A /= "NO_CHANGE") then
                            DOA_zd := (others => 'X');
			    end if;
                        end if;
                    elsif (WEA_ipd = 'X') then
                        if (VALID_ADDRA) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                        end if;
                        DOA_zd := (others => 'X');
                    else 
                        if (VALID_ADDRA) then
                            DOA_zd := MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW));
                        else
                            DOA_zd := (others => 'X');
                        end if;
                    end if;
                    if (SSRA_ipd = '1') then
                        DOA_zd := SRVA_A(0 downto 0) ;
                    elsif (SSRA_ipd = 'X') then
                        DOA_zd := (others => 'X');
                    end if;
                elsif (CLKA_ipd = 'X') then
                    if (WEA_ipd /= '0') then
                        if (VALID_ADDRA) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                        end if;
                    end if;
                    if (WRITE_MODE_A /= "NO_CHANGE" ) then
                    DOA_zd := (others => 'X');
		    end if;
                end if; 
            elsif (CLKA_ipd'event AND CLKA_ipd'last_value = 'X') then
                if (CLKA_ipd = '1') then
                    if (WEA_ipd /= '0') then
                        if (VALID_ADDRA) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                        end if;
                    end if;
                    DOA_zd := (others => 'X');
                end if;
            end if; 
        elsif (ENA_ipd = 'X') then
            if (CLKA_ipd'event AND CLKA_ipd'last_value /= '1') then
                if (CLKA_ipd /= '0') then
                    if (WEA_ipd /= '0') then
                        if (VALID_ADDRA) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                            MEM := (others => 'X');
                        end if;
                    end if;
                    DOA_zd := (others => 'X');
                end if;
            end if; 
        end if; 
    else
        DOA_zd := (others => 'X');
    end if; 
    
    --
    -- Port B
    --
    if (GSR_ipd = '1') then
        DOB_zd :=  INI_B(0 downto 0) ;
    elsif (GSR_ipd = '0') then
        if (ENB_ipd = '1') then
            if (CLKB_ipd'event AND CLKB_ipd'last_value = '0') then
                if (CLKB_ipd = '1') then
                    if (WEB_ipd = '1') then
                        if (VALID_ADDRB) then
                            if(WRITE_MODE_B = "WRITE_FIRST") then
                             DOB_zd := DIB_ipd;
                           elsif(WRITE_MODE_B = "READ_FIRST") then
                             DOB_zd := MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) ;
                          elsif(WRITE_MODE_B /= "NO_CHANGE") then
                            assert false report
                            " Wrong value for write_mode, assuming WRITE_FIRST "
                            severity warning;
                            DOB_zd := DIB_ipd;
                          end if;
                            if (WRITE_MODE_B /= "READ_FIRST") then
                            MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := DIB_ipd;
                            else WR_B_LATER := TRUE;
                            end if;
                            if (ENA_ipd = '1' AND VALID_ADDRA AND HAS_OVERLAP) then
                                if (Tviol_CLKA_CLKB_posedge = 'X') then
                                    if (WEA_ipd /= '0') then
                                        if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "READ_FIRST" ) then
                                        COLLISION (ADDRB_ipd, OLP_LSB, OLP_MSB, "write",
                                        "port B", "port A", InstancePath, MEM);
					end if;
					if (SSRA_ipd = '0' AND WRITE_MODE_A /= "NO_CHANGE" AND WRITE_MODE_B /= "READ_FIRST") then
                                        DOA_zd (DOA_OV_MSB downto DOA_OV_LSB) := (others => 'X');
					end if;
                                  	if (WRITE_MODE_A /= "READ_FIRST" AND WRITE_MODE_B /= "NO_CHANGE" ) then
                                        DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others => 'X');
					end if;
                                    else
                                        if (WRITE_MODE_B /= "READ_FIRST" ) then
                                        COLLISION (ADDRB_ipd, OLP_LSB, OLP_MSB, "read",
                                        "port B", "port A", InstancePath, MEM);
					end if;
					if (SSRA_ipd = '0' AND WRITE_MODE_B /= "READ_FIRST" ) then
                                        DOA_zd (DOA_OV_MSB downto DOA_OV_LSB) := (others => 'X');
					end if;
                                    end if;
                                end if;
                            end if;
                        else
                            SET_MEM_TO_X(ADDRB_ipd, MEM);
                            if (WRITE_MODE_B /= "NO_CHANGE" ) then
                            DOB_zd := (others => 'X');
			    end if;
                        end if;
                    elsif (WEB_ipd = 'X') then
                        if (VALID_ADDRB) then
                            MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRB_ipd, MEM);
                        end if;
                        DOB_zd := (others => 'X');
                    else 
                        if (VALID_ADDRB) then
                            DOB_zd := MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW));
			    if (Tviol_CLKB_CLKA_posedge = 'X' AND HAS_OVERLAP = TRUE AND WRITE_MODE_A /= "READ_FIRST") then
                             DOB_zd (DOB_OV_MSB downto DOB_OV_LSB) := (others => 'X');
                            end if;
                        else
                            DOB_zd := (others => 'X');
                        end if;
                    end if;
                    if (SSRB_ipd = '1') then
                        DOB_zd := SRVA_B(0 downto 0) ;
                    elsif (SSRB_ipd = 'X') then
                        DOB_zd := (others => 'X');
                    end if;
                elsif (CLKB_ipd = 'X') then
                    if (WEB_ipd /= '0') then
                        if (VALID_ADDRB) then
                            MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRB_ipd, MEM);
                        end if;
                    end if;
                    DOB_zd := (others => 'X');
                end if; 
            elsif (CLKB_ipd'event AND CLKB_ipd'last_value = 'X') then
                if (CLKB_ipd = '1') then
                    if (WEB_ipd /= '0') then
                        if (VALID_ADDRB) then
                            MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRB_ipd, MEM);
                        end if;
                    end if;
                    DOB_zd := (others => 'X');
                end if;
            end if; 
        elsif (ENB_ipd = 'X') then
            if (CLKB_ipd'event AND CLKB_ipd'last_value /= '1') then
                if (CLKB_ipd /= '0') then
                    if (WEB_ipd /= '0') then
                        if (VALID_ADDRB) then
                            MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRB_ipd, MEM);
                            MEM := (others => 'X');
                        end if;
                    end if;
                    DOB_zd := (others => 'X');
                end if;
            end if; 
        end if; 
    else
        DOB_zd := (others => 'X');
    end if;

    if (WR_A_LATER = TRUE ) then

        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := DIA_ipd ;
    end if;

    if (WR_B_LATER = TRUE ) then

        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := DIB_ipd;
    end if;

    if (WR_A_LATER AND WR_B_LATER ) then
        COLLISION (ADDRB_ipd, OLP_LSB, OLP_MSB, "write", "port B", "port A", InstancePath, MEM);
    end if;

    DOA_zd(0) := Violation XOR DOA_zd(0);

    DOB_zd(0) := Violation XOR DOB_zd(0);

    ----------------------
    --  Path Delay Section
    ----------------------

    VitalPathDelay01 (   
      OutSignal => DOA(0),
      GlitchData => DOA_GlitchData0,
      OutSignalName => "DOA(0)",    
      OutTemp => DOA_zd(0),  
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(0),  (ENA_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOA(0),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);


    VitalPathDelay01 (   
      OutSignal => DOB(0),
      GlitchData => DOB_GlitchData0,
      OutSignalName => "DOB(0)",    
      OutTemp => DOB_zd(0),  
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(0),  (ENB_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOB(0),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
