                            if(WRITE_MODE = "WRITE_FIRST") then
                              DO_zd := DI_ipd;
                            elsif(WRITE_MODE = "READ_FIRST") then
                              DO_zd := MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW));
                            elsif(WRITE_MODE /= "NO_CHANGE") then
                              assert false report
                              " Wrong value for WRITE_MODE, assuming WRITE_FIRST "
                              severity warning;
                              DO_zd := DI_ipd;
                            end if;
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := DI_ipd;
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                            DO_zd := (others => 'X');
                        end if;
                    elsif (WE_ipd = 'X') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                        DO_zd := (others => 'X');
                    else 
                        if (VALID_ADDR) then
                            DO_zd := MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW));
                        else
                            DO_zd := (others => 'X');
                        end if;
                    end if;
                    if (SSR_ipd = '1') then
                        DO_zd := SRVA(1 downto 0 );
                    elsif (SSR_ipd = 'X') then
                        DO_zd := (others => 'X');
                    end if;
                elsif (CLK_ipd = 'X') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                end if; 
            elsif (CLK_ipd'event AND CLK_ipd'last_value = 'X') then
                if (CLK_ipd = '1') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                end if;
            end if; 
        elsif (EN_ipd = 'X') then
            if (CLK_ipd'event AND CLK_ipd'last_value /= '1') then
                if (CLK_ipd /= '0') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                end if;
            end if; 
        end if; 
    else
        DO_zd := (others => 'X');
    end if;

    DO_zd(1)  := Violation XOR DO_zd(1);
    DO_zd(0)  := Violation XOR DO_zd(0);

    ----------------------
    --  Path Delay Section
    ----------------------

    VitalPathDelay01 (   
      OutSignal => DO(1),
      GlitchData => DO_GlitchData1,
      OutSignalName => "DO(1)",    
      OutTemp => DO_zd(1),  
      Paths => (0 => (CLK_ipd'last_event,  tpd_CLK_DO(1),  (EN_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,  tpd_GSR_DO(1),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DO(0),
      GlitchData => DO_GlitchData0,
      OutSignalName => "DO(0)",    
      OutTemp => DO_zd(0),  
      Paths => (0 => (CLK_ipd'last_event,  tpd_CLK_DO(0),  (EN_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,  tpd_GSR_DO(0),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    wait on GSR_ipd, CLK_ipd, WE_ipd, EN_ipd, SSR_ipd, DI_ipd, ADDR_ipd;

  end process VITALBehavior;

end X_RAMB16_S2_V;

