    --  Path Delay Section
    ----------------------

    VitalPathDelay01 (   
      OutSignal => DOA(1),
      GlitchData => DOA_GlitchData1,
      OutSignalName => "DOA(1)",    
      OutTemp => DOA_zd(1),  
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(1),  (ENA_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOA(1),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
