      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(0),  (ENA_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOA(0),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(15),
      GlitchData => DOB_GlitchData15,
      OutSignalName => "DOB(15)",
      OutTemp => DOB_zd(15),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(15),  (ENB_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOB(15),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
