       tipd_GSR   : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_SSRA  : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_SSRB  : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_CLKA  : VitalDelayType01 := ( 0.0 ns,  0.0 ns);
       tipd_CLKB  : VitalDelayType01 := ( 0.0 ns,  0.0 ns);

