          TimingData              => Tmkr_ADDR2_CLK_posedge,
          TestSignal              => ADDR_ipd(2),
          TestSignalName          => "ADDR(2)",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName           => "CLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_ADDR_CLK_posedge_posedge(2),
          SetupLow                => tsetup_ADDR_CLK_negedge_posedge(2),
          HoldLow                => thold_ADDR_CLK_posedge_posedge(2),
          HoldHigh                 => thold_ADDR_CLK_negedge_posedge(2),
          CheckEnabled            => TO_X01(EN_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB16_S4",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_ADDR1_CLK_posedge,
          TimingData              => Tmkr_ADDR1_CLK_posedge,
          TestSignal              => ADDR_ipd(1),
          TestSignalName          => "ADDR(1)",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName           => "CLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_ADDR_CLK_posedge_posedge(1),
          SetupLow                => tsetup_ADDR_CLK_negedge_posedge(1),
          HoldLow                => thold_ADDR_CLK_posedge_posedge(1),
          HoldHigh                 => thold_ADDR_CLK_negedge_posedge(1),
          CheckEnabled            => TO_X01(EN_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB16_S4",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_ADDR0_CLK_posedge,
          TimingData              => Tmkr_ADDR0_CLK_posedge,
          TestSignal              => ADDR_ipd(0),
          TestSignalName          => "ADDR(0)",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName           => "CLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_ADDR_CLK_posedge_posedge(0),
          SetupLow                => tsetup_ADDR_CLK_negedge_posedge(0),
          HoldLow                => thold_ADDR_CLK_posedge_posedge(0),
          HoldHigh                 => thold_ADDR_CLK_negedge_posedge(0),
          CheckEnabled            => TO_X01(EN_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB16_S4",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck (
          Violation               => Pviol_CLK,
          PeriodData              => PInfo_CLK,
          TestSignal              => CLK_ipd,
          TestSignalName          => "CLK",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLK_posedge,
          PulseWidthLow           => tpw_CLK_negedge,
          CheckEnabled            => TO_X01(EN_ipd) /= '0',
          HeaderMsg               => InstancePath &"/X_RAMB16_S4",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck ( 
          Violation               => Pviol_GSR,
          PeriodData              => PInfo_GSR,
          TestSignal              => GSR_ipd,
          TestSignalName          => "GSR",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_GSR_posedge,
          PulseWidthLow           => 0 ns,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/X_RAMB16_S4",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);
 
    end if;

    Violation := 
                 Tviol_DI3_CLK_posedge   or Tviol_DI2_CLK_posedge   or
                 Tviol_DI1_CLK_posedge   or Tviol_DI0_CLK_posedge   or
                 Tviol_EN_CLK_posedge    or Tviol_WE_CLK_posedge    or
                 Tviol_SSR_CLK_posedge   or Tviol_ADDR11_CLK_posedge or
                 Tviol_ADDR10_CLK_posedge or Tviol_ADDR9_CLK_posedge or 
                 Tviol_ADDR8_CLK_posedge or Tviol_ADDR7_CLK_posedge or
                 Tviol_ADDR6_CLK_posedge or Tviol_ADDR5_CLK_posedge or
                 Tviol_ADDR4_CLK_posedge or Tviol_ADDR3_CLK_posedge or
                 Tviol_ADDR2_CLK_posedge or Tviol_ADDR1_CLK_posedge or 
                 Tviol_ADDR0_CLK_posedge or Pviol_CLK;

    -------------------------
    --  Functionality Section
    -------------------------
    VALID_ADDR := ADDR_IS_VALID(ADDR_ipd);

    if (VALID_ADDR) then
        ADDRESS := SLV_TO_INT(ADDR_ipd);
    end if;

    if (GSR_ipd = '1') then
        DO_zd := INI(3 downto 0 );
    elsif (GSR_ipd = '0') then
        if (EN_ipd = '1') then
            if (CLK_ipd'event AND CLK_ipd'last_value = '0') then
                if (CLK_ipd = '1') then
                    if (WE_ipd = '1') then
                        if (VALID_ADDR) then
                            if(WRITE_MODE = "WRITE_FIRST") then
                              DO_zd := DI_ipd;
                            elsif(WRITE_MODE = "READ_FIRST") then
                              DO_zd := MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW));
                            elsif(WRITE_MODE /= "NO_CHANGE") then
                              assert false report
                              " Wrong value for WRITE_MODE, assuming WRITE_FIRST "
                              severity warning;
                              DO_zd := DI_ipd;
                            end if;
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := DI_ipd;
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                            DO_zd := (others => 'X');
                        end if;
                    elsif (WE_ipd = 'X') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                        DO_zd := (others => 'X');
                    else 
                        if (VALID_ADDR) then
                            DO_zd := MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW));
                        else
                            DO_zd := (others => 'X');
                        end if;
                    end if;
                    if (SSR_ipd = '1') then
                        DO_zd := SRVA(3 downto 0 );
                    elsif (SSR_ipd = 'X') then
                        DO_zd := (others => 'X');
                    end if;
                elsif (CLK_ipd = 'X') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                end if; 
            elsif (CLK_ipd'event AND CLK_ipd'last_value = 'X') then
                if (CLK_ipd = '1') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                end if;
            end if; 
        elsif (EN_ipd = 'X') then
            if (CLK_ipd'event AND CLK_ipd'last_value /= '1') then
                if (CLK_ipd /= '0') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                end if;
            end if; 
        end if; 
    else
        DO_zd := (others => 'X');
    end if;

    DO_zd(3)  := Violation XOR DO_zd(3);
    DO_zd(2)  := Violation XOR DO_zd(2);
    DO_zd(1)  := Violation XOR DO_zd(1);
    DO_zd(0)  := Violation XOR DO_zd(0);

    ----------------------
    --  Path Delay Section
    ----------------------

    VitalPathDelay01 (
      OutSignal => DO(3),
      GlitchData => DO_GlitchData3,
      OutSignalName => "DO(3)",
      OutTemp => DO_zd(3),
      Paths => (0 => (CLK_ipd'last_event,  tpd_CLK_DO(3),  (EN_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,  tpd_GSR_DO(3),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DO(2),
      GlitchData => DO_GlitchData2,
      OutSignalName => "DO(2)",    
      OutTemp => DO_zd(2),  
      Paths => (0 => (CLK_ipd'last_event,  tpd_CLK_DO(2),  (EN_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,  tpd_GSR_DO(2),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DO(1),
      GlitchData => DO_GlitchData1,
      OutSignalName => "DO(1)",    
      OutTemp => DO_zd(1),  
      Paths => (0 => (CLK_ipd'last_event,  tpd_CLK_DO(1),  (EN_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,  tpd_GSR_DO(1),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (   
      OutSignal => DO(0),
      GlitchData => DO_GlitchData0,
      OutSignalName => "DO(0)",    
      OutTemp => DO_zd(0),  
      Paths => (0 => (CLK_ipd'last_event,  tpd_CLK_DO(0),  (EN_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,  tpd_GSR_DO(0),  TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    wait on GSR_ipd, CLK_ipd, WE_ipd, EN_ipd, SSR_ipd, DI_ipd, ADDR_ipd;

  end process VITALBehavior;

end X_RAMB16_S4_V;

