      OutSignalName => "DOB(13)",
      OutTemp => DOB_zd(13),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(13),  (ENB_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOB(13),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
