      OutSignalName => "DOB(12)",
      OutTemp => DOB_zd(12),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(12),  (ENB_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOB(12),   TRUE)),
