          SetupLow                => tsetup_ADDR_CLK_negedge_posedge(3),
          HoldLow                => thold_ADDR_CLK_posedge_posedge(3),
          HoldHigh                 => thold_ADDR_CLK_negedge_posedge(3),
          CheckEnabled            => TO_X01(EN_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB16_S9",
