          TestSignalName          => "ADDR(0)",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName           => "CLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_ADDR_CLK_posedge_posedge(0),
          SetupLow                => tsetup_ADDR_CLK_negedge_posedge(0),
          HoldLow                => thold_ADDR_CLK_posedge_posedge(0),
          HoldHigh                 => thold_ADDR_CLK_negedge_posedge(0),
          CheckEnabled            => TO_X01(EN_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB16_S9",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck (
          Violation               => Pviol_CLK,
          PeriodData              => PInfo_CLK,
          TestSignal              => CLK_ipd,
          TestSignalName          => "CLK",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLK_posedge,
          PulseWidthLow           => tpw_CLK_negedge,
          CheckEnabled            => TO_X01(EN_ipd) /= '0',
          HeaderMsg               => InstancePath &"/X_RAMB16_S9",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck ( 
          Violation               => Pviol_GSR,
          PeriodData              => PInfo_GSR,
          TestSignal              => GSR_ipd,
          TestSignalName          => "GSR",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_GSR_posedge,
          PulseWidthLow           => 0 ns,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/X_RAMB16_S9",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);
 
    end if;

    Violation := 
                 Tviol_DI7_CLK_posedge   or Tviol_DI6_CLK_posedge   or
                 Tviol_DI5_CLK_posedge   or Tviol_DI4_CLK_posedge   or
                 Tviol_DI3_CLK_posedge   or Tviol_DI2_CLK_posedge   or
                 Tviol_DI1_CLK_posedge   or Tviol_DI0_CLK_posedge   or
                 Tviol_DIP0_CLK_posedge   or
                 Tviol_EN_CLK_posedge    or Tviol_WE_CLK_posedge    or
                 Tviol_SSR_CLK_posedge   or 
