                        DOP_zd := SRVA(8 downto 8 );
                    elsif (SSR_ipd = 'X') then
                        DO_zd := (others => 'X');
                        DOP_zd := (others => 'X');
                    end if;
                elsif (CLK_ipd = 'X') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                            MEMP((ADDRESS*DIPW + DIPW_1) downto (ADDRESS*DIPW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                            SET_MEM_TO_X(ADDR_ipd, MEMP);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                    DOP_zd := (others => 'X');
                end if; 
            elsif (CLK_ipd'event AND CLK_ipd'last_value = 'X') then
                if (CLK_ipd = '1') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                            MEMP((ADDRESS*DIPW + DIPW_1) downto (ADDRESS*DIPW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                            SET_MEM_TO_X(ADDR_ipd, MEMP);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                    DOP_zd := (others => 'X');
                end if;
            end if; 
        elsif (EN_ipd = 'X') then
            if (CLK_ipd'event AND CLK_ipd'last_value /= '1') then
                if (CLK_ipd /= '0') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                            MEMP((ADDRESS*DIPW + DIPW_1) downto (ADDRESS*DIPW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                            SET_MEM_TO_X(ADDR_ipd, MEMP);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                    DOP_zd := (others => 'X');
                end if;
            end if; 
        end if; 
    else
        DO_zd := (others => 'X');
        DOP_zd := (others => 'X');
    end if;

    DO_zd(7)  := Violation XOR DO_zd(7);
    DO_zd(6)  := Violation XOR DO_zd(6);
    DO_zd(5)  := Violation XOR DO_zd(5);
    DO_zd(4)  := Violation XOR DO_zd(4);
    DO_zd(3)  := Violation XOR DO_zd(3);
    DO_zd(2)  := Violation XOR DO_zd(2);
    DO_zd(1)  := Violation XOR DO_zd(1);
    DO_zd(0)  := Violation XOR DO_zd(0);

