      OutTemp => DO_zd(4),  
      Paths => (0 => (CLK_ipd'last_event,  tpd_CLK_DO(4),  (EN_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,  tpd_GSR_DO(4),  TRUE)),
      Mode => OnEvent,
