                    if (WEB_ipd /= '0') then
                        if (VALID_ADDRB) then
                            MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                            MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRB_ipd, MEM);
                            SET_MEM_TO_X(ADDRB_ipd, MEMP);
                        end if;
                    end if;
                    DOB_zd := (others => 'X');
                    DOPB_zd := (others => 'X');
                end if;
            end if; 
        elsif (ENB_ipd = 'X') then
            if (CLKB_ipd'event AND CLKB_ipd'last_value /= '1') then
                if (CLKB_ipd /= '0') then
                    if (WEB_ipd /= '0') then
                        if (VALID_ADDRB) then
                            MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := (others => 'X');
                            MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRB_ipd, MEM);
                            SET_MEM_TO_X(ADDRB_ipd, MEMP);
                            MEM := (others => 'X');
                            MEMP := (others => 'X');
                        end if;
                    end if;
                    DOB_zd := (others => 'X');
                    DOPB_zd := (others => 'X');
                end if;
            end if; 
        end if; 
    else
        DOB_zd := (others => 'X');
        DOPB_zd := (others => 'X');
    end if;

    if (WR_A_LATER = TRUE ) then

        MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := DIA_ipd ;
        MEMP((ADDRESS_A*DIPAW + DIPAW_1) downto (ADDRESS_A*DIPAW)) := DIPA_ipd ;
    end if;

    if (WR_B_LATER = TRUE ) then

        MEM((ADDRESS_B*DIBW + DIBW_1) downto (ADDRESS_B*DIBW)) := DIB_ipd;
        MEMP((ADDRESS_B*DIPBW + DIPBW_1) downto (ADDRESS_B*DIPBW)) := DIPB_ipd;
    end if;

    if (WR_A_LATER AND WR_B_LATER ) then
        COLLISION (ADDRB_ipd, OLP_LSB, OLP_MSB, "write", "port B", "port A", InstancePath, MEM);
        COLLISION (ADDRB_ipd, OLPP_LSB, OLPP_MSB, "write", "port B", "port A", InstancePath, MEMP);
    end if;

    DOA_zd(7)  := Violation XOR DOA_zd(7);
    DOA_zd(6)  := Violation XOR DOA_zd(6);
    DOA_zd(5)  := Violation XOR DOA_zd(5);
    DOA_zd(4)  := Violation XOR DOA_zd(4);
    DOA_zd(3)  := Violation XOR DOA_zd(3);
    DOA_zd(2)  := Violation XOR DOA_zd(2);
    DOA_zd(1)  := Violation XOR DOA_zd(1);
    DOA_zd(0)  := Violation XOR DOA_zd(0);
    DOPA_zd(0)  := Violation XOR DOPA_zd(0);

    DOB_zd(7)  := Violation XOR DOB_zd(7);
    DOB_zd(6)  := Violation XOR DOB_zd(6);
    DOB_zd(5)  := Violation XOR DOB_zd(5);
    DOB_zd(4)  := Violation XOR DOB_zd(4);
    DOB_zd(3)  := Violation XOR DOB_zd(3);
    DOB_zd(2)  := Violation XOR DOB_zd(2);
    DOB_zd(1)  := Violation XOR DOB_zd(1);
    DOB_zd(0)  := Violation XOR DOB_zd(0);
    DOPB_zd(0)  := Violation XOR DOPB_zd(0);

    ----------------------
    --  Path Delay Section
    ----------------------

    VitalPathDelay01 (
      OutSignal => DOA(7),
      GlitchData => DOA_GlitchData7,
      OutSignalName => "DOA(7)",
      OutTemp => DOA_zd(7),
      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(7),  (ENA_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOA(7),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
