      Paths => (0 => (CLKA_ipd'last_event,  tpd_CLKA_DOA(5),  (ENA_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOA(5),   TRUE)),
