          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLK_posedge,
          PulseWidthLow           => tpw_CLK_negedge,
          CheckEnabled            => TO_X01(EN_ipd) /= '0',
          HeaderMsg               => InstancePath &"/X_RAMB4_S1",
          Xon                     => Xon,
          MsgOn                   => True,
