    -------------------------
    --  Functionality Section
    -------------------------
    VALID_ADDR := ADDR_IS_VALID(ADDR_ipd);

    if (VALID_ADDR) then
        ADDRESS := SLV_TO_INT(ADDR_ipd);
    end if;

    if (GSR_ipd = '1') then
        DO_zd := (others => '0');
    elsif (GSR_ipd = '0') then
        if (EN_ipd = '1') then
            if (CLK_ipd'event AND CLK_ipd'last_value = '0') then
                if (CLK_ipd = '1') then
                    if (WE_ipd = '1') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := DI_ipd;
                            DO_zd := DI_ipd;
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                            DO_zd := (others => 'X');
                        end if;
                    elsif (WE_ipd = 'X') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                        DO_zd := (others => 'X');
                    else 
                        if (VALID_ADDR) then
                            DO_zd := MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW));
                        else
                            DO_zd := (others => 'X');
                        end if;
                    end if;
                    if (RST_ipd = '1') then
                        DO_zd := (others => '0');
                    elsif (RST_ipd = 'X') then
                        DO_zd := (others => 'X');
                    end if;
                elsif (CLK_ipd = 'X') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                end if; 
            elsif (CLK_ipd'event AND CLK_ipd'last_value = 'X') then
                if (CLK_ipd = '1') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                end if;
            end if; 
        elsif (EN_ipd = 'X') then
            if (CLK_ipd'event AND CLK_ipd'last_value /= '1') then
                if (CLK_ipd /= '0') then
                    if (WE_ipd /= '0') then
                        if (VALID_ADDR) then
                            MEM((ADDRESS*DIW + DIW_1) downto (ADDRESS*DIW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDR_ipd, MEM);
                        end if;
                    end if;
                    DO_zd := (others => 'X');
                end if;
            end if; 
        end if; 
    else
        DO_zd := (others => 'X');
    end if;

