      OutSignalName => "DOB(14)",
      OutTemp => DOB_zd(14),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(14),  (ENB_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOB(14),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
