      OutSignalName => "DOB(11)",
      OutTemp => DOB_zd(11),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(11),  (ENB_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOB(11),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(10),
      GlitchData => DOB_GlitchData10,
      OutSignalName => "DOB(10)",
      OutTemp => DOB_zd(10),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(10),  (ENB_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOB(10),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(9),
