      OutSignalName => "DOB(9)",
      OutTemp => DOB_zd(9),
      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(9),  (ENB_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOB(9),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
