      Paths => (0 => (CLKB_ipd'last_event,  tpd_CLKB_DOB(8),  (ENB_ipd /= '0' AND GSR_ipd /= '1')),
                1 => (GSR_ipd'last_event,   tpd_GSR_DOB(8),   TRUE)),
      Mode => OnEvent,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

    VitalPathDelay01 (
      OutSignal => DOB(7),
