                        if (VALID_ADDRA) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                        end if;
                    end if;
                    DOA_zd := (others => 'X');
                end if;
            end if; 
        elsif (ENA_ipd = 'X') then
            if (CLKA_ipd'event AND CLKA_ipd'last_value /= '1') then
                if (CLKA_ipd /= '0') then
                    if (WEA_ipd /= '0') then
                        if (VALID_ADDRA) then
                            MEM((ADDRESS_A*DIAW + DIAW_1) downto (ADDRESS_A*DIAW)) := (others => 'X');
                        else
                            SET_MEM_TO_X(ADDRA_ipd, MEM);
                            MEM := (others => 'X');
                        end if;
                    end if;
                    DOA_zd := (others => 'X');
                end if;
            end if; 
        end if; 
    else
        DOA_zd := (others => 'X');
    end if; 
    
    --
