    variable FIRST_TIME : boolean := TRUE;

  begin -- process

    if (FIRST_TIME) then
        wait until (GSR_ipd = '1' or CLK_ipd'last_value = '0' or CLK_ipd'last_value = '1');
        FIRST_TIME := FALSE;
    end if;

    ------------------------
    --  Timing Check Section
    ------------------------
    if (TimingChecksOn) then

         VitalSetupHoldCheck (
          Violation               => Tviol_DI3_CLK_posedge,
