          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB4_S4",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);
 
         VitalRecoveryRemovalCheck ( 
          Violation               => Tviol_GSR_CLK_posedge,
          TimingData              => Tmkr_GSR_CLK_posedge,
          TestSignal              => GSR_ipd,
          TestSignalName          => "GSR",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
