          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_RAMB4_S4",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_ADDR4_CLK_posedge,
          TimingData              => Tmkr_ADDR4_CLK_posedge,
          TestSignal              => ADDR_ipd(4),
          TestSignalName          => "ADDR(4)",
          TestDelay               => 0 ns,
