       thold_WEB_CLKB_negedge_posedge    : VitalDelayType := 0.01 ns;
       thold_RSTB_CLKB_posedge_posedge   : VitalDelayType := 0.01 ns;
       thold_RSTB_CLKB_negedge_posedge   : VitalDelayType := 0.01 ns;
