       thold_ADDRB_CLKB_negedge_posedge  : VitalDelayArrayType (8 downto 0)  := (others => 0.01 ns);

       -- VITAL minimum pulse width

       tpw_CLKA_posedge : VitalDelayType := 0.01 ns;
