begin -- architecture

  ----------------------
  --  Wire Delay Section
  ----------------------
  WireDelay : block
  begin
    VitalWireDelay (ADDRA_ipd(0), ADDRA(0), tipd_ADDRA(0));
    VitalWireDelay (ADDRA_ipd(1), ADDRA(1), tipd_ADDRA(1));
    VitalWireDelay (ADDRA_ipd(2), ADDRA(2), tipd_ADDRA(2));
