architecture X_SRL16E_V of X_SRL16E is

  attribute VITAL_LEVEL0 of X_SRL16E_V : architecture is TRUE;

  -- Local signals used to propagate input wire delay

  signal A0_ipd  : std_ulogic := 'X';
  signal A1_ipd  : std_ulogic := 'X';
  signal A2_ipd  : std_ulogic := 'X';
  signal A3_ipd  : std_ulogic := 'X';

  signal D_ipd   : std_ulogic := 'X';
  signal CE_ipd  : std_ulogic := 'X';
  signal CLK_ipd : std_ulogic := 'X';

  signal Q_zd    : std_ulogic := 'X';
  signal SHIFT_REG : std_logic_vector (16 downto 0) := ('X' & To_StdLogicVector(INIT));

 
begin -- architecture

  ----------------------
  --  Wire Delay Section
  ----------------------
  WireDelay : block
  begin
    VitalWireDelay (A0_ipd,   A0,  tipd_A0);
    VitalWireDelay (A1_ipd,   A1,  tipd_A1);
    VitalWireDelay (A2_ipd,   A2,  tipd_A2);
    VitalWireDelay (A3_ipd,   A3,  tipd_A3);

    VitalWireDelay (D_ipd,    D,   tipd_D);
    VitalWireDelay (CE_ipd,   CE,  tipd_CE);
    VitalWireDelay (CLK_ipd,  CLK, tipd_CLK);
  end block;

  --------------------
  -- X_SRL16E Behavior
  --------------------
  VITALReadBehavior : process (A0_ipd, A1_ipd, A2_ipd, A3_ipd, SHIFT_REG)

    -- Local variables 
    -- Local variables used for functionality
    variable ADDR : std_logic_vector(3 downto 0);
    variable VALID_ADDR : boolean := FALSE;
    variable LENGTH : integer;

  begin -- process

    ADDR := (A3_ipd, A2_ipd, A1_ipd, A0_ipd);
    VALID_ADDR := ADDR_IS_VALID(SLV => ADDR);

    if (VALID_ADDR) then
        LENGTH := SLV_TO_INT(SLV => ADDR);
    else
        LENGTH := 16;
    end if;
    Q_zd <= SHIFT_REG(LENGTH);

  end process VITALReadBehavior;

--------------------------------

  VITALWriteBehavior : process

    variable FIRST_TIME : boolean := TRUE;

  begin -- process

    if (FIRST_TIME) then
        wait until ((CE_ipd = '0' or CE_ipd = '1') and 
                   (CLK_ipd'last_value = '0' or CLK_ipd'last_value = '1') and
                   (CLK_ipd = '0' or CLK_ipd = '1'));
        FIRST_TIME := FALSE;
    end if;

    if (CLK_ipd'event AND CLK_ipd'last_value = '0') then
        if (CLK_ipd = '1') then
            if (CE_ipd = '1') then
                    for I in 15 downto 1 loop
                        SHIFT_REG(I) <= SHIFT_REG(I-1);
                    end loop;
                SHIFT_REG(0) <= D_ipd;
            elsif (CE_ipd = 'X') then
                SHIFT_REG <= (others => 'X');
            end if;
        elsif (CLK_ipd = 'X') then
            if (CE_ipd /= '0') then
		for i in 0 to 15 loop
		    if ( SHIFT_REG(i) /= D_ipd ) then
                        SHIFT_REG <= (others => 'X');
			exit;
		    end if;
		end loop;
            end if;
        end if;
    elsif (CLK_ipd'event AND CLK_ipd'last_value = 'X') then
        if (CLK_ipd = '1') then
            if (CE_ipd /= '0') then
                for i in 0 to 15 loop
                    if ( SHIFT_REG(i) /= D_ipd ) then
                        SHIFT_REG <= (others => 'X');
                        exit;
                    end if;
                end loop;
            end if;
        end if;
    end if;

   wait on CLK_ipd;

  end process VITALWriteBehavior;

  ----------------------
  --  Timing Section
  ----------------------
  VITALTiming : process (A0_ipd, A1_ipd, A2_ipd, A3_ipd, CLK_ipd, CE_ipd, D_ipd, Q_zd)
    variable Tviol_D_CLK_posedge  : std_ulogic := '0';
    variable Tviol_CE_CLK_posedge : std_ulogic := '0';

    variable Tmkr_D_CLK_posedge   : VitalTimingDataType := VitalTimingDataInit;
    variable Tmkr_CE_CLK_posedge  : VitalTimingDataType := VitalTimingDataInit;

    variable PViol_CLK : std_ulogic := '0';
    variable PInfo_CLK : VitalPeriodDataType := VitalPeriodDataInit;

    variable Violation : std_ulogic := '0';
    variable Q_zdt     : std_ulogic := '0';
    variable Q_GlitchData : VitalGlitchDataType;

    begin

    Q_zdt := Q_zd;


    ------------------------
    --  Timing Check Section
    ------------------------
    if (TimingChecksOn) then

         VitalSetupHoldCheck (
          Violation               => Tviol_D_CLK_posedge,
          TimingData              => Tmkr_D_CLK_posedge,
          TestSignal              => D_ipd,
          TestSignalName          => "D",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName           => "CLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_D_CLK_posedge_posedge,
          SetupLow                => tsetup_D_CLK_negedge_posedge,
          HoldLow                => thold_D_CLK_posedge_posedge,
          HoldHigh                 => thold_D_CLK_negedge_posedge,
          CheckEnabled            => TO_X01(CE_ipd) /= '0',
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_SRL16E",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalSetupHoldCheck (
          Violation               => Tviol_CE_CLK_posedge,
          TimingData              => Tmkr_CE_CLK_posedge,
          TestSignal              => CE_ipd,
          TestSignalName          => "CE",
          TestDelay               => 0 ns,
          RefSignal               => CLK_ipd,
          RefSignalName           => "CLK",
          RefDelay                => 0 ns,
          SetupHigh               => tsetup_CE_CLK_posedge_posedge,
          SetupLow                => tsetup_CE_CLK_negedge_posedge,
          HoldLow                => thold_CE_CLK_posedge_posedge,
          HoldHigh                 => thold_CE_CLK_negedge_posedge,
          CheckEnabled            => TRUE,
          RefTransition           => 'R',
          HeaderMsg               => InstancePath & "/X_SRL16E",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

         VitalPeriodPulseCheck (
          Violation               => Pviol_CLK,
          PeriodData              => PInfo_CLK,
          TestSignal              => CLK_ipd,
          TestSignalName          => "CLK",
          TestDelay               => 0 ns,
          Period                  => 0 ns,
          PulseWidthHigh          => tpw_CLK_posedge,
          PulseWidthLow           => tpw_CLK_negedge,
          CheckEnabled            => TRUE,
          HeaderMsg               => InstancePath &"/X_SRL16E",
          Xon                     => Xon,
          MsgOn                   => True,
          MsgSeverity             => WARNING);

    end if;

    Violation := Tviol_D_CLK_posedge or Tviol_CE_CLK_posedge or
                 Pviol_CLK;

    Q_zdt := Violation XOR Q_zdt;

    ----------------------
    --  Path Delay Section
    ----------------------
    VitalPathDelay01 (
      OutSignal => Q,
      GlitchData => Q_GlitchData,
      OutSignalName => "Q",
      OutTemp => Q_zdt,
      Paths => (0 => (CLK_ipd'last_event, tpd_CLK_Q, (CE_ipd /= '0')),
                1 => (A0_ipd'last_event,  tpd_A0_Q,  TRUE),
                2 => (A1_ipd'last_event,  tpd_A1_Q,  TRUE),
                3 => (A2_ipd'last_event,  tpd_A2_Q,  TRUE),
                4 => (A3_ipd'last_event,  tpd_A3_Q,  TRUE)),
      Mode => VitalInertial,
      Xon => Xon,
      MsgOn => MsgOn,
      MsgSeverity => WARNING);

  end process VITALTiming;

end X_SRL16E_V;

